-- ════════════════════════════════════════════════════════
-- 226 — Lot 13 du cinquieme recensement : les fabriques meres
-- ────────────────────────────────────────────────────────
-- LES 27 FICHES CUBAINES RELUES contre les 27 pages officielles de
-- habanos.com (14 septembre 2026), cubancigarwebsite.com et la presse
-- du metier (2011, 2016, 2019). Rien n'est reecrit : un paragraphe est
-- AJOUTE a chaque histoire, six langues, qui dit ou la marque est
-- roulee et par qui — la question que l'atlas pose a toutes les
-- autres depuis le lot 4.
--
-- CE QUE LA RELECTURE A TROUVE. Quinze fiches sans fabrique nommee ;
-- sept qui en nommaient une fausse ou perimee — Bolivar (chez Romeo y
-- Julieta : basee a Partagas, dit Habanos), Trinidad (El Laguito :
-- Pinar del Rio, dit Habanos), Punch (H. Upmann : La Corona, dit
-- Habanos), Hoyo, Quintero et Vegas Robaina (« El Rey del Mundo », une
-- fabrique qui a cede son batiment a Partagas en 2010 et son nom a
-- Romeo y Julieta), Partagas (Industria 520 : San Carlos 806, dit
-- Habanos). Quatre marques dont aucune source ne nomme la mere —
-- Fonseca, Juan Lopez, Rafael Gonzalez, Sancho Panza : la fiche le
-- dit. Six dates qui divergent de la page officielle, ecrites.
--
-- La regle 220 s'applique : Habanos ne publie pas la carte des
-- fabriques, et chaque paragraphe commence par le dire — politique
-- des fabriques meres depuis 2002, roulage possible ailleurs. Les
-- `factory` sont reecrits, les `source` aussi, deux `founded`
-- corriges (El Rey del Mundo, Jose L. Piedra) et deux qui ecrivent
-- leur divergence (Rafael Gonzalez, Vegueros).
--
-- L'ajout est idempotent : garde par un marqueur propre a chaque
-- langue (« fabrique mere », « mother factory », « fabrica madre »,
-- « Mutterfabrik », « 母厂 », « مصنع أمّ »).
-- ════════════════════════════════════════════════════════

-- ── Bolivar ──
UPDATE `brands` SET `factory` = 'Fabrique mère Partagás (Francisco Pérez Germán), San Carlos 806, Centro Habana — la page officielle la dit basée là ; roulage possible ailleurs sous sa supervision', `source` = 'habanos.com, page officielle Bolívar (lue le 14 septembre 2026 : créée en 1902 ; basée aujourd''hui à la fabrique Partagás ; tripe longue ; Soberano 2018, Regentes 2021) — le champ de date de cette fiche portait 1901 alors que son texte disait 1902, corrigé par la migration 196 ; cubancigarwebsite.com « Tobacco and Cigar Production » (fabriques mères depuis 2002 ; Partagás mère de Bolívar, La Gloria Cubana, Ramón Allones, Quai d''Orsay ; déménagement de 2010, effondrement partiel d''Industria 520 en 2020) ; cigaraficionado.com « The New Partagás Factory » (sept.-oct. 2016 : San Carlos, ex-El Rey del Mundo, 209 rouleurs) et « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Bolivar';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Partagás — la Francisco Pérez Germán —, qui a quitté en 2010 le bâtiment jaune d''Industria 520, derrière le Capitole, pour l''ancienne fabrique El Rey del Mundo, San Carlos 806, à Centro Habana ; le vieux bâtiment, promis à un musée puis à un hôtel, s''est partiellement effondré en 2020. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, dans le groupe de quatre dit de haute valeur — Bolívar, Punch, Ramón Allones, Trinidad. La page officielle la dit basée à la fabrique Partagás, ce que la presse du métier confirme ; l''atlas l''écrivait chez Romeo y Julieta, et se corrige.') WHERE `name` = 'Bolivar' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Partagás — the Francisco Pérez Germán —, which left the yellow building at Industria 520, behind the Capitol, in 2010 for the former El Rey del Mundo factory at San Carlos 806, Centro Habana; the old building, promised to a museum and then a hotel, partly collapsed in 2020. Since 2019 Habanos has placed it among its twenty-one portfolio brands, in the group of four called high-value — Bolívar, Punch, Ramón Allones, Trinidad. The official page says it is based at the Partagás factory, which the trade press confirms; this atlas had it at Romeo y Julieta, and corrects itself.') WHERE `name` = 'Bolivar' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Partagás — la Francisco Pérez Germán —, que dejó en 2010 el edificio amarillo de Industria 520, detrás del Capitolio, por la antigua fábrica El Rey del Mundo, San Carlos 806, en Centro Habana; el viejo edificio, prometido a un museo y luego a un hotel, se derrumbó en parte en 2020. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, en el grupo de cuatro llamado de alto valor — Bolívar, Punch, Ramón Allones, Trinidad. La página oficial la dice basada en la fábrica Partagás, lo que la prensa del oficio confirma; el atlas la ponía en Romeo y Julieta, y se corrige.') WHERE `name` = 'Bolivar' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Partagás — die Francisco Pérez Germán —, die 2010 das gelbe Gebäude an der Industria 520 hinter dem Kapitol für die frühere Fabrik El Rey del Mundo, San Carlos 806, in Centro Habana verließ; das alte Gebäude, erst einem Museum, dann einem Hotel versprochen, stürzte 2020 teilweise ein. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, in der Vierergruppe, die hochwertig genannt wird — Bolívar, Punch, Ramón Allones, Trinidad. Die offizielle Seite nennt sie bei der Fabrik Partagás ansässig, was die Fachpresse bestätigt; dieser Atlas hatte sie bei Romeo y Julieta und korrigiert sich.') WHERE `name` = 'Bolivar' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是帕塔加斯——即 Francisco Pérez Germán 厂——2010年离开国会大厦后面工业街520号的黄色建筑，迁入中哈瓦那圣卡洛斯街806号原 El Rey del Mundo 厂；老楼先说要做博物馆、后说做酒店，2020年部分坍塌。 自2019年起，Habanos 把它列入二十一个组合品牌，属于所谓高价值的四个品牌一组——Bolívar、Punch、Ramón Allones、Trinidad。 官方页面说它设在帕塔加斯厂，行业媒体也证实；本图集原先写在罗密欧与朱丽叶厂，予以更正。') WHERE `name` = 'Bolivar' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Partagás — مصنع فرانسيسكو بيريس خيرمان — الذي غادر سنة 2010 المبنى الأصفر في إندوستريا 520 خلف الكابيتول إلى مصنع El Rey del Mundo السابق، سان كارلوس 806، في سنترو هابانا؛ أمّا المبنى القديم، الموعود بمتحف ثمّ بفندق، فانهار جزئيًّا سنة 2020. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، في مجموعة الأربع المسمّاة عالية القيمة — Bolívar وPunch وRamón Allones وTrinidad. تقول الصفحة الرسمية إنّها مقيمة في مصنع Partagás، وتؤكّد ذلك الصحافة المتخصّصة؛ وكان هذا الأطلس يضعها عند Romeo y Julieta، ويصحّح نفسه.') WHERE `name` = 'Bolivar' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Cohiba ──
UPDATE `brands` SET `factory` = 'El Laguito, Cubanacán (La Havane) — manufacture ouverte en 1966 pour la marque, nommée par la page officielle ; certains modules roulés ailleurs selon la presse du métier', `source` = 'habanos.com, page officielle Cohiba (lue le 14 septembre 2026 : créée en 1966, cadeaux d''État jusqu''en 1982 ; fabriquée à El Laguito ; deux des trois feuilles de tripe subissent une fermentation supplémentaire ; Línea 1492 en 1992, Maduro 5 en 2007, Behike en 2010 avec la feuille de medio tiempo) ; cubancigarwebsite.com « Tobacco and Cigar Production » (El Laguito, 1966, ancienne villa de Cubanacán, mère de Cohiba) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011 : des Cohiba roulés aussi à la fabrique H. Upmann) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'Cohiba';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique est El Laguito, à Cubanacán, dans une ancienne villa de l''ouest de La Havane ouverte en 1966 pour elle — la page officielle le dit, et c''est la seule marque dont Habanos nomme la fabrique. Depuis 2019, Habanos la range dans ses six marques globales, vendues sur tous ses marchés et dans toutes les Casas del Habano. La presse du métier note que certains modules ont aussi été roulés à la fabrique H. Upmann et à Partagás ; El Laguito reste la mère.') WHERE `name` = 'Cohiba' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its factory is El Laguito, in Cubanacán, a former mansion in western Havana opened in 1966 for it — the official page says so, and it is the only brand whose factory Habanos names. Since 2019 Habanos has placed it among its six global brands, sold in all its markets and in every Casa del Habano. The trade press notes that some sizes have also been rolled at the H. Upmann factory and at Partagás; El Laguito remains the mother.') WHERE `name` = 'Cohiba' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica es El Laguito, en Cubanacán, en una antigua mansión del oeste de La Habana abierta en 1966 para ella — la página oficial lo dice, y es la única marca cuya fábrica nombra Habanos. Desde 2019 Habanos la clasifica entre sus seis marcas globales, vendidas en todos sus mercados y en todas las Casas del Habano. La prensa del oficio anota que algunos módulos también se han liado en la fábrica H. Upmann y en Partagás; El Laguito sigue siendo la madre.') WHERE `name` = 'Cohiba' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Fabrik ist El Laguito in Cubanacán, eine frühere Villa im Westen Havannas, 1966 für sie eröffnet — die offizielle Seite sagt es, und sie ist die einzige Marke, deren Fabrik Habanos nennt. Seit 2019 zählt Habanos sie zu seinen sechs globalen Marken, die auf allen Märkten und in jeder Casa del Habano verkauft werden. Die Fachpresse vermerkt, dass einige Formate auch in der Fabrik H. Upmann und bei Partagás gerollt wurden; El Laguito bleibt die Mutter.') WHERE `name` = 'Cohiba' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的工厂是位于库瓦纳坎的 El Laguito，哈瓦那西郊一座旧宅，1966年为它而设——官方页面这么写，这也是 Habanos 唯一点名工厂的品牌。 自2019年起，Habanos 把它列为六个全球品牌之一，在其所有市场和每一家 Casa del Habano 销售。 行业媒体指出，部分规格也曾在乌普曼厂和帕塔加斯厂卷制；El Laguito 仍是母厂。') WHERE `name` = 'Cohiba' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها هو El Laguito في كوباناكان، فيلا قديمة في غرب هافانا فُتحت سنة 1966 من أجلها — تقول الصفحة الرسمية ذلك، وهي العلامة الوحيدة التي تسمّي Habanos مصنعها. منذ 2019 تصنّفها Habanos ضمن علاماتها العالمية الستّ، التي تُباع في كلّ أسواقها وفي كلّ Casa del Habano. تلاحظ الصحافة المتخصّصة أنّ بعض القياسات لُفّت أيضًا في مصنع H. Upmann وفي Partagás؛ ويبقى El Laguito الأمّ.') WHERE `name` = 'Cohiba' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Cuaba ──
UPDATE `brands` SET `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane ; la marque est née en 1996 à la fabrique Romeo y Julieta, dit la page officielle', `source` = 'habanos.com, page officielle Cuaba (lue le 14 septembre 2026 : style des doubles figurados de la fin du XIXe, relancé en 1996 à la fabrique Romeo y Julieta ; Divinos, Tradicionales, Generosos, Exclusivos, puis Distinguido, Diadema et Salomón depuis 2003 ; cuaba, buisson taíno servant à allumer) ; cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de Cuaba) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011) et « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Cuaba';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la fait naître en 1996 à la fabrique Romeo y Julieta, qui remit au goût du jour les doubles figurados ; la presse du métier place ensuite sa fabrique mère à La Corona. Tout est roulé à la main en tripe longue.') WHERE `name` = 'Cuaba' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page has it born in 1996 at the Romeo y Julieta factory, which revived double figurados; the trade press then places its mother factory at La Corona. Everything is hand-rolled with long filler.') WHERE `name` = 'Cuaba' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la hace nacer en 1996 en la fábrica Romeo y Julieta, que puso de nuevo de moda los dobles figurados; la prensa del oficio sitúa luego su fábrica madre en La Corona. Todo se lía a mano con tripa larga.') WHERE `name` = 'Cuaba' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite lässt sie 1996 in der Fabrik Romeo y Julieta entstehen, die die Doppelfigurados wiederbelebte; die Fachpresse verortet ihre Mutterfabrik dann bei La Corona. Alles wird von Hand mit Longfiller gerollt.') WHERE `name` = 'Cuaba' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它1996年诞生于罗密欧与朱丽叶厂，该厂重新推出双头异形雪茄；行业媒体随后把它的母厂定在 La Corona。全部手工长茄芯。') WHERE `name` = 'Cuaba' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تجعلها الصفحة الرسمية تولد سنة 1996 في مصنع Romeo y Julieta الذي أعاد الفيغورادو المزدوج إلى الرواج؛ ثمّ تضع الصحافة المتخصّصة مصنعها الأمّ في La Corona. كلّه ملفوف يدويًّا بحشوة طويلة.') WHERE `name` = 'Cuaba' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Diplomáticos ──
UPDATE `brands` SET `factory` = 'Fabrique mère H. Upmann (José Martí), Belascoaín, Centro Habana — selon la presse du métier ; Habanos ne nomme pas la fabrique', `source` = 'habanos.com, page officielle Diplomáticos (lue le 14 septembre 2026 : marque des années 1960, numérotée comme Montecristo ; tripe longue, Vuelta Abajo, medium à full) ; cubancigarwebsite.com « Tobacco and Cigar Production » (H. Upmann mère de Montecristo et Diplomáticos) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011 : Diplomáticos roulée à la fabrique de Belascoaín) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; créée en 1966 pour le marché français selon l''ancienne lecture de la page' WHERE `name` = 'Diplomáticos';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est H. Upmann — la José Martí, ainsi nommée depuis 1960 —, qui a changé plusieurs fois d''adresse et occupe depuis 2011 l''ancien bâtiment Romeo y Julieta de Belascoaín, à Centro Habana. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la date des années 1960 et la dit numérotée comme Montecristo, dont elle est née ; elle ne nomme pas sa fabrique, que la presse du métier place chez H. Upmann, comme Montecristo.') WHERE `name` = 'Diplomáticos' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is H. Upmann — the José Martí, so named since 1960 —, which has moved several times and has occupied since 2011 the former Romeo y Julieta building on Belascoaín, Centro Habana. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it to the 1960s and says it is numbered like Montecristo, from which it was born; it does not name its factory, which the trade press places at H. Upmann, like Montecristo.') WHERE `name` = 'Diplomáticos' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es H. Upmann — la José Martí, así llamada desde 1960 —, que cambió varias veces de dirección y ocupa desde 2011 el antiguo edificio Romeo y Julieta de Belascoaín, en Centro Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la fecha en los años sesenta y la dice numerada como Montecristo, de la que nació; no nombra su fábrica, que la prensa del oficio sitúa en H. Upmann, como Montecristo.') WHERE `name` = 'Diplomáticos' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist H. Upmann — die José Martí, so benannt seit 1960 —, die mehrmals umzog und seit 2011 das frühere Romeo-y-Julieta-Gebäude an der Belascoaín in Centro Habana belegt. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie in die 1960er Jahre und nennt sie nummeriert wie Montecristo, aus der sie hervorging; sie nennt ihre Fabrik nicht, die die Fachpresse bei H. Upmann verortet, wie Montecristo.') WHERE `name` = 'Diplomáticos' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是乌普曼——即1960年起得名的 José Martí 厂——几度搬迁，2011年起占用中哈瓦那贝拉斯科艾因街原罗密欧与朱丽叶厂房。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把它定在1960年代，并说它像 Montecristo 一样以数字命名，它正是从后者衍生；页面没有点名工厂，行业媒体把它和 Montecristo 一样放在乌普曼厂。') WHERE `name` = 'Diplomáticos' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو H. Upmann — مصنع خوسيه مارتي، بهذا الاسم منذ 1960 — الذي غيّر عنوانه مرارًا ويشغل منذ 2011 مبنى Romeo y Julieta السابق في بيلاسكوين، سنترو هابانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤرّخها الصفحة الرسمية في الستينيات وتقول إنّها مرقّمة مثل Montecristo التي وُلدت منها؛ ولا تسمّي مصنعها، الذي تضعه الصحافة المتخصّصة عند H. Upmann مثل Montecristo.') WHERE `name` = 'Diplomáticos' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── El Rey del Mundo ──
UPDATE `brands` SET `factory` = 'Fabrique mère Romeo y Julieta (ex-Carlos Baliño, la fabrique qui portait son nom), La Havane — selon la presse du métier', `source` = 'habanos.com, page officielle El Rey del Mundo (lue le 14 septembre 2026 : en 1882, sous Antonio Allones, lancement d''une marque de qualité et de prix élevés ; tripe longue, light à medium ; beaucoup utilisée en éditions régionales) — l''ancienne lecture de la fiche attribuait 1848 à la page officielle ; en.wikipedia.org (fondée en 1848 par Emilio Ohmstedt) ; cubancigarwebsite.com « Tobacco and Cigar Production » (l''ancienne fabrique El Rey del Mundo / Carlos Baliño rebaptisée Romeo y Julieta, mère d''El Rey del Mundo et Saint Luis Rey) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)', `founded` = '1848 (Ohmstedt) ou 1882 (Allones) — La Havane' WHERE `name` = 'El Rey del Mundo';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Romeo y Julieta : le bâtiment historique de Belascoaín a été cédé à H. Upmann en 2011, et c''est l''ancienne fabrique Carlos Baliño — celle qui portait le nom d''El Rey del Mundo —, rebaptisée, qui tient ce rôle depuis la fin des années 2010, selon la presse spécialisée. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. Deux dates pour une marque : 1848 et Emilio Ohmstedt selon l''usage et Wikipédia, 1882 et Antonio Allones selon la page officielle, qui fait de cette année-là le lancement de la marque haut de gamme ; la fiche écrit les deux. La fabrique qui portait son nom a cédé son bâtiment à Partagás en 2010 et son nom à Romeo y Julieta ; la marque suit cette dernière.') WHERE `name` = 'El Rey del Mundo' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Romeo y Julieta: the historic Belascoaín building was ceded to H. Upmann in 2011, and it is the former Carlos Baliño factory — the one that bore the El Rey del Mundo name —, renamed, that has held the role since the late 2010s, according to the specialist press. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. Two dates for one brand: 1848 and Emilio Ohmstedt by usage and Wikipedia, 1882 and Antonio Allones by the official page, which makes that year the launch of the premium brand; the entry writes both. The factory that bore its name ceded its building to Partagás in 2010 and its name to Romeo y Julieta; the brand follows the latter.') WHERE `name` = 'El Rey del Mundo' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Romeo y Julieta: el edificio histórico de Belascoaín se cedió a H. Upmann en 2011, y es la antigua fábrica Carlos Baliño — la que llevaba el nombre de El Rey del Mundo —, rebautizada, la que cumple ese papel desde finales de los años 2010, según la prensa especializada. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. Dos fechas para una marca: 1848 y Emilio Ohmstedt según el uso y Wikipedia, 1882 y Antonio Allones según la página oficial, que hace de ese año el lanzamiento de la marca de alta gama; la ficha escribe las dos. La fábrica que llevaba su nombre cedió su edificio a Partagás en 2010 y su nombre a Romeo y Julieta; la marca sigue a esta última.') WHERE `name` = 'El Rey del Mundo' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Romeo y Julieta: Das historische Gebäude an der Belascoaín wurde 2011 an H. Upmann abgetreten, und die frühere Fabrik Carlos Baliño — die den Namen El Rey del Mundo trug —, umbenannt, hat diese Rolle seit Ende der 2010er Jahre inne, laut Fachpresse. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Zwei Daten für eine Marke: 1848 und Emilio Ohmstedt nach Gebrauch und Wikipedia, 1882 und Antonio Allones nach der offiziellen Seite, die jenes Jahr zum Start der Premiummarke macht; der Eintrag schreibt beide. Die Fabrik, die ihren Namen trug, trat ihr Gebäude 2010 an Partagás ab und ihren Namen an Romeo y Julieta; die Marke folgt Letzterer.') WHERE `name` = 'El Rey del Mundo' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是罗密欧与朱丽叶：贝拉斯科艾因街的历史厂房2011年让给了乌普曼，据专业媒体，自2010年代末起由原 Carlos Baliño 厂——曾以 El Rey del Mundo 为名——更名后担任这一角色。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 一个品牌两个日期：按惯例和维基百科是1848年、埃米利奥·奥姆施泰特；按官方页面是1882年、安东尼奥·阿约内斯，页面把那一年当作高端品牌的推出；词条两者都写。曾以它为名的工厂2010年把厂房让给帕塔加斯、把名字让给罗密欧与朱丽叶；品牌跟随后者。') WHERE `name` = 'El Rey del Mundo' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Romeo y Julieta: تنازل المبنى التاريخي في بيلاسكوين لـH. Upmann سنة 2011، ومصنع كارلوس بالينيو السابق — الذي كان يحمل اسم El Rey del Mundo — هو الذي يؤدّي هذا الدور بعد إعادة تسميته منذ أواخر عقد 2010، بحسب الصحافة المتخصّصة. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تاريخان لعلامة واحدة: 1848 وإميليو أومشتيت بحسب العرف وويكيبيديا، و1882 وأنطونيو أيونيس بحسب الصفحة الرسمية التي تجعل من تلك السنة إطلاق العلامة الراقية؛ تكتب البطاقة الاثنين. والمصنع الذي كان يحمل اسمها تنازل عن مبناه لـPartagás سنة 2010 وعن اسمه لـRomeo y Julieta؛ وتتبع العلامة هذه الأخيرة.') WHERE `name` = 'El Rey del Mundo' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Fonseca ──
UPDATE `brands` SET `factory` = 'Fabrique mère non nommée par Habanos ni par la presse du métier consultée ; roulée à Cuba sous le régime des fabriques mères', `source` = 'habanos.com, page officielle Fonseca (lue le 14 septembre 2026 : Don Francisco Fonseca, dernière décennie du XIXe siècle — pas d''année ; papier de soie ; certaines vitoles en tripe longue, d''autres en tripe courte ; light) ; en.wikipedia.org donne 1892, d''autres sources 1891 — l''atlas retient 1892 et écrit la variance ; cubancigarwebsite.com et cigaraficionado.com (2011, 2016) ne nomment pas sa fabrique mère ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Fonseca';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Aucune source consultée — ni Habanos, ni la presse du métier — ne nomme sa fabrique mère ; la fiche le dit plutôt que de choisir. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle ne date la fondation que de la dernière décennie du XIXe siècle et dit la gamme roulée à la main, une partie en tripe longue, une partie en tripe courte — et toujours enveloppée de papier de soie, la marque de Don Francisco.') WHERE `name` = 'Fonseca' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. No source consulted — neither Habanos nor the trade press — names its mother factory; the entry says so rather than choosing. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates the founding only to the last decade of the nineteenth century and says the range is hand-rolled, part long filler, part short filler — and always wrapped in tissue paper, Don Francisco''s mark.') WHERE `name` = 'Fonseca' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Ninguna fuente consultada — ni Habanos, ni la prensa del oficio — nombra su fábrica madre; la ficha lo dice en vez de elegir. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial solo fecha la fundación en la última década del siglo XIX y dice la gama liada a mano, una parte con tripa larga, otra con tripa corta — y siempre envuelta en papel de seda, la marca de Don Francisco.') WHERE `name` = 'Fonseca' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Keine befragte Quelle — weder Habanos noch die Fachpresse — nennt ihre Mutterfabrik; der Eintrag sagt es, statt zu wählen. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert die Gründung nur ins letzte Jahrzehnt des 19. Jahrhunderts und nennt die Palette handgerollt, teils Longfiller, teils Shortfiller — und stets in Seidenpapier gehüllt, Don Franciscos Zeichen.') WHERE `name` = 'Fonseca' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 查阅的来源——无论 Habanos 还是行业媒体——都没有点名它的母厂；词条如实说明，而不是自行挑选。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面只把创立定在十九世纪最后十年，说全系列手工卷制，一部分长茄芯，一部分短茄芯——并且始终裹着薄纸，那是堂弗朗西斯科的标记。') WHERE `name` = 'Fonseca' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا يسمّي أيّ مصدر راجعناه — لا Habanos ولا الصحافة المتخصّصة — مصنعها الأمّ؛ وتقول البطاقة ذلك بدل أن تختار. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. لا تؤرّخ الصفحة الرسمية التأسيس إلّا في العقد الأخير من القرن التاسع عشر، وتقول إنّ المجموعة ملفوفة يدويًّا، بعضها بحشوة طويلة وبعضها بحشوة قصيرة — ومغلّفة دائمًا بورق حرير، علامة دون فرانسيسكو.') WHERE `name` = 'Fonseca' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── H. Upmann ──
UPDATE `brands` SET `factory` = 'Fabrique H. Upmann (José Martí depuis 1960), Belascoaín 853, Centro Habana — l''ancien bâtiment Romeo y Julieta, occupé depuis 2011', `source` = 'habanos.com, page officielle H. Upmann (lue le 14 septembre 2026 : Herman Upmann, banquier allemand, installé en 1844 ; onze médailles d''or au XIXe ; Magnum 50 en 2008, Half Corona en 2011, Magnum 54 en 2016, Sir Winston Gran Reserva 2017) ; lahabana.gob.cu « fábrica de cigarros H. Upmann » (2 juillet 2020 : José Martí depuis 1960 ; Belascoaín 853 ; San Miguel 85, Virtudes 609 en 1890, 20 de Mayo le 29 mai 1955 ; Compay Segundo rouleur dix-neuf ans) ; cubancigarwebsite.com « Tobacco and Cigar Production » (nouveau bâtiment de 2004 inondé, installation dans l''ancienne Romeo y Julieta en 2011 ; mère de Montecristo et Diplomáticos) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011 : Belascoaín 852, 204 rouleurs) et « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'H. Upmann';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est H. Upmann — la José Martí, ainsi nommée depuis 1960 —, qui a changé plusieurs fois d''adresse et occupe depuis 2011 l''ancien bâtiment Romeo y Julieta de Belascoaín, à Centro Habana. Depuis 2019, Habanos la range dans ses six marques globales, vendues sur tous ses marchés et dans toutes les Casas del Habano. Le portail de la ville de La Havane retrace ses adresses — San Miguel 85 au XIXe siècle, Virtudes 609 en 1890, la calle 20 de Mayo au Cerro en 1955, Belascoaín aujourd''hui — et rappelle qu''un rouleur y travailla dix-neuf ans : Francisco Repilado, Compay Segundo. La fabrique est aussi la mère de Montecristo et de Diplomáticos.') WHERE `name` = 'H. Upmann' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is H. Upmann — the José Martí, so named since 1960 —, which has moved several times and has occupied since 2011 the former Romeo y Julieta building on Belascoaín, Centro Habana. Since 2019 Habanos has placed it among its six global brands, sold in all its markets and in every Casa del Habano. Havana''s city portal traces its addresses — San Miguel 85 in the nineteenth century, Virtudes 609 in 1890, calle 20 de Mayo in Cerro in 1955, Belascoaín today — and recalls that a roller worked there nineteen years: Francisco Repilado, Compay Segundo. The factory is also the mother of Montecristo and Diplomáticos.') WHERE `name` = 'H. Upmann' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es H. Upmann — la José Martí, así llamada desde 1960 —, que cambió varias veces de dirección y ocupa desde 2011 el antiguo edificio Romeo y Julieta de Belascoaín, en Centro Habana. Desde 2019 Habanos la clasifica entre sus seis marcas globales, vendidas en todos sus mercados y en todas las Casas del Habano. El portal de la ciudad de La Habana repasa sus direcciones — San Miguel 85 en el siglo XIX, Virtudes 609 en 1890, la calle 20 de Mayo en el Cerro en 1955, Belascoaín hoy — y recuerda que un torcedor trabajó allí diecinueve años: Francisco Repilado, Compay Segundo. La fábrica es también la madre de Montecristo y de Diplomáticos.') WHERE `name` = 'H. Upmann' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist H. Upmann — die José Martí, so benannt seit 1960 —, die mehrmals umzog und seit 2011 das frühere Romeo-y-Julieta-Gebäude an der Belascoaín in Centro Habana belegt. Seit 2019 zählt Habanos sie zu seinen sechs globalen Marken, die auf allen Märkten und in jeder Casa del Habano verkauft werden. Das Stadtportal Havannas zeichnet ihre Adressen nach — San Miguel 85 im 19. Jahrhundert, Virtudes 609 1890, die Calle 20 de Mayo im Cerro 1955, Belascoaín heute — und erinnert daran, dass ein Roller dort neunzehn Jahre arbeitete: Francisco Repilado, Compay Segundo. Die Fabrik ist auch die Mutter von Montecristo und Diplomáticos.') WHERE `name` = 'H. Upmann' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是乌普曼——即1960年起得名的 José Martí 厂——几度搬迁，2011年起占用中哈瓦那贝拉斯科艾因街原罗密欧与朱丽叶厂房。 自2019年起，Habanos 把它列为六个全球品牌之一，在其所有市场和每一家 Casa del Habano 销售。 哈瓦那市政门户网站追溯了它的地址——十九世纪的圣米格尔街85号、1890年的维尔图德斯街609号、1955年塞罗区的五月二十日街、如今的贝拉斯科艾因街——并提到一位卷工在那里干了十九年：弗朗西斯科·雷皮拉多，即康帕伊·塞贡多。该厂也是 Montecristo 和 Diplomáticos 的母厂。') WHERE `name` = 'H. Upmann' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو H. Upmann — مصنع خوسيه مارتي، بهذا الاسم منذ 1960 — الذي غيّر عنوانه مرارًا ويشغل منذ 2011 مبنى Romeo y Julieta السابق في بيلاسكوين، سنترو هابانا. منذ 2019 تصنّفها Habanos ضمن علاماتها العالمية الستّ، التي تُباع في كلّ أسواقها وفي كلّ Casa del Habano. يتتبّع بوّابة مدينة هافانا عناوينه — سان ميغيل 85 في القرن التاسع عشر، وفيرتوديس 609 سنة 1890، وشارع 20 دي مايو في سيرو سنة 1955، وبيلاسكوين اليوم — ويذكّر بأنّ لفّافًا عمل فيه تسعة عشر عامًا: فرانسيسكو ريبيلادو، كومباي سيغوندو. والمصنع هو أيضًا أمّ Montecristo وDiplomáticos.') WHERE `name` = 'H. Upmann' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Hoyo de Monterrey ──
UPDATE `brands` SET `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane — avec Punch depuis 1931, dit la page officielle de Punch ; la plantation d''origine porte l''inscription José Gener 1860', `source` = 'habanos.com, pages officielles Hoyo de Monterrey et Punch (lues le 14 septembre 2026 : plantation de San Juan y Martínez, inscription José Gener 1860 ; Petit Robustos 2004, Epicure Especial 2008, Le Hoyo de San Juan 2014, Le Hoyo de Río Seco 2018, Primaveras 2021 ; Punch a rejoint Hoyo en 1931, les deux produites à La Corona) ; cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona, 1889, Cerro, mère de Hoyo, Punch, San Cristóbal, La Flor de Cano, Cuaba, Por Larrañaga) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'Hoyo de Monterrey';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses six marques globales, vendues sur tous ses marchés et dans toutes les Casas del Habano. La page officielle de Punch dit les deux marques produites ensemble à La Corona depuis que Punch a rejoint Hoyo en 1931 ; l''atlas l''écrivait chez El Rey del Mundo, une fabrique qui n''existe plus sous ce nom, et se corrige. La porte de la vega d''origine, à San Juan y Martínez, porte l''inscription José Gener 1860 — cinq ans avant la date de la marque.') WHERE `name` = 'Hoyo de Monterrey' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its six global brands, sold in all its markets and in every Casa del Habano. Punch''s official page says the two brands have been produced together at La Corona since Punch joined Hoyo in 1931; this atlas had it at El Rey del Mundo, a factory that no longer exists under that name, and corrects itself. The gate of the original vega, at San Juan y Martínez, bears the inscription José Gener 1860 — five years before the brand''s date.') WHERE `name` = 'Hoyo de Monterrey' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus seis marcas globales, vendidas en todos sus mercados y en todas las Casas del Habano. La página oficial de Punch dice las dos marcas producidas juntas en La Corona desde que Punch se unió a Hoyo en 1931; el atlas la ponía en El Rey del Mundo, una fábrica que ya no existe con ese nombre, y se corrige. La puerta de la vega de origen, en San Juan y Martínez, lleva la inscripción José Gener 1860 — cinco años antes de la fecha de la marca.') WHERE `name` = 'Hoyo de Monterrey' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen sechs globalen Marken, die auf allen Märkten und in jeder Casa del Habano verkauft werden. Die offizielle Seite von Punch nennt beide Marken seit 1931, als Punch zu Hoyo kam, gemeinsam bei La Corona produziert; dieser Atlas hatte sie bei El Rey del Mundo, einer Fabrik, die unter diesem Namen nicht mehr besteht, und korrigiert sich. Das Tor der ursprünglichen Vega in San Juan y Martínez trägt die Inschrift José Gener 1860 — fünf Jahre vor dem Datum der Marke.') WHERE `name` = 'Hoyo de Monterrey' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列为六个全球品牌之一，在其所有市场和每一家 Casa del Habano 销售。 Punch 的官方页面说，自1931年 Punch 并入 Hoyo 以来，两个品牌一直在 La Corona 一同生产；本图集原先写在 El Rey del Mundo，那家厂已不再以此名存在，予以更正。圣胡安-马丁内斯原产烟田的大门刻着 José Gener 1860——比品牌日期早五年。') WHERE `name` = 'Hoyo de Monterrey' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علاماتها العالمية الستّ، التي تُباع في كلّ أسواقها وفي كلّ Casa del Habano. تقول الصفحة الرسمية لـPunch إنّ العلامتين تُنتجان معًا في La Corona منذ انضمام Punch إلى Hoyo سنة 1931؛ وكان هذا الأطلس يضعها عند El Rey del Mundo، وهو مصنع لم يعد قائمًا بهذا الاسم، ويصحّح نفسه. ويحمل باب المزرعة الأصلية في سان خوان إي مارتينيس نقش José Gener 1860 — قبل تاريخ العلامة بخمس سنوات.') WHERE `name` = 'Hoyo de Monterrey' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── José L. Piedra ──
UPDATE `brands` SET `factory` = 'Fabrique mère provinciale de Holguín, selon la presse du métier ; tripe courte de Remedios (Vuelta Arriba), roulée main', `source` = 'habanos.com, page officielle José L. Piedra (lue le 14 septembre 2026 : famille venue des Asturies dans les années 1880, installée près de Santa Clara ; marque fondée par la deuxième génération, José Lamadrid Piedra ; sept vitoles en tripe courte roulée main, tabac de Remedios seulement ; nouvelle image, Petit Caballeros) ; cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique provinciale de Holguín mère de José L. Piedra ; Remedios, Vuelta Arriba, source de toutes ses feuilles) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019 : marque de volume)', `founded` = 'Famille arrivée en 1880s ; marque : 2e génération' WHERE `name` = 'José L. Piedra';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est une fabrique provinciale de Holguín, dans l''est de l''île — loin de la Vuelta Abajo, dont elle n''utilise pas le tabac. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle dit la famille Piedra arrivée des Asturies dans les années 1880 et installée près de Santa Clara, et la marque fondée par la deuxième génération, José Lamadrid Piedra — la fiche datait l''arrivée, pas la marque, et l''écrit désormais. Toute la gamme est en tripe courte roulée main, avec le seul tabac de Remedios.') WHERE `name` = 'José L. Piedra' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is a provincial factory in Holguín, in the east of the island — far from the Vuelta Abajo, whose tobacco it does not use. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page has the Piedra family arriving from Asturias in the 1880s and settling near Santa Clara, and the brand founded by the second generation, José Lamadrid Piedra — the entry dated the arrival, not the brand, and now says so. The whole range is hand-rolled short filler, with Remedios tobacco only.') WHERE `name` = 'José L. Piedra' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es una fábrica provincial de Holguín, en el este de la isla — lejos de la Vuelta Abajo, cuyo tabaco no usa. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial dice la familia Piedra llegada de Asturias en los años 1880 e instalada cerca de Santa Clara, y la marca fundada por la segunda generación, José Lamadrid Piedra — la ficha fechaba la llegada, no la marca, y ahora lo dice. Toda la gama es tripa corta liada a mano, solo con tabaco de Remedios.') WHERE `name` = 'José L. Piedra' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist eine Provinzfabrik in Holguín im Osten der Insel — fern der Vuelta Abajo, deren Tabak sie nicht verwendet. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite lässt die Familie Piedra in den 1880er Jahren aus Asturien kommen und sich bei Santa Clara niederlassen, die Marke gegründet von der zweiten Generation, José Lamadrid Piedra — der Eintrag datierte die Ankunft, nicht die Marke, und sagt es nun. Die ganze Palette ist handgerollter Shortfiller, allein mit Remedios-Tabak.') WHERE `name` = 'José L. Piedra' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是岛东部奥尔金的一家省属工厂——远离下维尔塔，也不用那里的烟叶。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面说皮耶德拉家族1880年代从阿斯图里亚斯来到古巴，定居在圣克拉拉附近，品牌由第二代何塞·拉马德里德·皮耶德拉创立——词条原先记的是到来的年代而非品牌，现在如实写明。全系列为手工短茄芯，只用雷梅迪奥斯烟叶。') WHERE `name` = 'José L. Piedra' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ مصنع إقليمي في هولغين شرق الجزيرة — بعيدًا عن فويلتا أباخو التي لا تستعمل تبغها. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. تقول الصفحة الرسمية إنّ عائلة بييدرا وصلت من أستورياس في ثمانينيات القرن التاسع عشر واستقرّت قرب سانتا كلارا، وإنّ العلامة أسّسها الجيل الثاني، خوسيه لامادريد بييدرا — كانت البطاقة تؤرّخ الوصول لا العلامة، وتقول ذلك الآن. والمجموعة كلّها حشوة قصيرة ملفوفة يدويًّا بتبغ ريميديوس وحده.') WHERE `name` = 'José L. Piedra' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Juan López ──
UPDATE `brands` SET `factory` = 'Fabrique mère non nommée par Habanos ni par la presse du métier consultée ; roulée à Cuba sous le régime des fabriques mères', `source` = 'habanos.com, page officielle Juan López (lue le 14 septembre 2026 : créée par un Espagnol du même nom dans les années 1870 ; Selección No. 1 et No. 2 ; Selección Especial pour les 150 ans de la marque et les 30 ans du réseau LCDH ; tripe longue, Vuelta Abajo, medium à full) ; en.wikipedia.org (1876) ; cubancigarwebsite.com et cigaraficionado.com (2011, 2016) ne nomment pas sa fabrique mère ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Juan López';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Aucune source consultée — ni Habanos, ni la presse du métier — ne nomme sa fabrique mère ; la fiche le dit plutôt que de choisir. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la date des années 1870 — la fiche garde 1876, l''année de l''usage — et réduit sa gamme régulière aux Selección No. 1 et No. 2, auxquelles s''est ajoutée une Selección Especial pour ses cent cinquante ans et les trente ans du réseau La Casa del Habano.') WHERE `name` = 'Juan López' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. No source consulted — neither Habanos nor the trade press — names its mother factory; the entry says so rather than choosing. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it to the 1870s — the entry keeps 1876, the year in use — and reduces its regular range to Selección No. 1 and No. 2, joined by a Selección Especial for its hundred and fiftieth year and the thirtieth of the La Casa del Habano network.') WHERE `name` = 'Juan López' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Ninguna fuente consultada — ni Habanos, ni la prensa del oficio — nombra su fábrica madre; la ficha lo dice en vez de elegir. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la fecha en los años 1870 — la ficha conserva 1876, el año en uso — y reduce su gama regular a las Selección No. 1 y No. 2, a las que se sumó una Selección Especial por sus ciento cincuenta años y los treinta de la red La Casa del Habano.') WHERE `name` = 'Juan López' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Keine befragte Quelle — weder Habanos noch die Fachpresse — nennt ihre Mutterfabrik; der Eintrag sagt es, statt zu wählen. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie in die 1870er Jahre — der Eintrag behält 1876, das gebräuchliche Jahr — und beschränkt ihr reguläres Sortiment auf Selección No. 1 und No. 2, ergänzt um eine Selección Especial zu ihrem hundertfünfzigsten Jahr und den dreißig Jahren des Netzes La Casa del Habano.') WHERE `name` = 'Juan López' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 查阅的来源——无论 Habanos 还是行业媒体——都没有点名它的母厂；词条如实说明，而不是自行挑选。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把它定在1870年代——词条保留通行的1876年——常规系列只剩 Selección No. 1 和 No. 2，另为品牌一百五十周年和 La Casa del Habano 网络三十周年加了一款 Selección Especial。') WHERE `name` = 'Juan López' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا يسمّي أيّ مصدر راجعناه — لا Habanos ولا الصحافة المتخصّصة — مصنعها الأمّ؛ وتقول البطاقة ذلك بدل أن تختار. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤرّخها الصفحة الرسمية في سبعينيات القرن التاسع عشر — تحتفظ البطاقة بـ1876، السنة المتداولة — وتختصر مجموعتها المنتظمة في Selección No. 1 وNo. 2، وأُضيفت إليهما Selección Especial بمناسبة مئة وخمسين عامًا للعلامة وثلاثين عامًا لشبكة La Casa del Habano.') WHERE `name` = 'Juan López' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── La Flor de Cano ──
UPDATE `brands` SET `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane — selon la presse du métier ; toute la gamme en tripe courte roulée main', `source` = 'habanos.com, page officielle La Flor de Cano (lue le 14 septembre 2026 : équilibre goût-arôme, prix moyen ; toute la gamme en tripe courte roulée main, dont la vitole Elegidos ; la page ne donne plus de date — une lecture antérieure lui attribuait 1884 et les frères Cano, retenus par l''atlas) ; cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de La Flor de Cano) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011) et « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'La Flor de Cano';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle actuelle ne date plus la marque — 1884 et les frères Cano viennent de l''usage et d''une lecture antérieure de la page — et dit toute la gamme, Elegidos compris, roulée à la main en tripe courte, à prix moyen. L''atlas admet la tripe courte roulée main, et le dit.') WHERE `name` = 'La Flor de Cano' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The current official page no longer dates the brand — 1884 and the Cano brothers come from usage and from an earlier reading of the page — and says the whole range, Elegidos included, is hand-rolled short filler, at a medium price. This atlas admits hand-rolled short filler, and says so.') WHERE `name` = 'La Flor de Cano' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial actual ya no fecha la marca — 1884 y los hermanos Cano vienen del uso y de una lectura anterior de la página — y dice toda la gama, Elegidos incluidos, liada a mano con tripa corta, a precio medio. Este atlas admite la tripa corta liada a mano, y lo dice.') WHERE `name` = 'La Flor de Cano' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die aktuelle offizielle Seite datiert die Marke nicht mehr — 1884 und die Brüder Cano stammen aus dem Gebrauch und einer früheren Lesung der Seite — und nennt die ganze Palette, Elegidos eingeschlossen, handgerollten Shortfiller zu mittlerem Preis. Dieser Atlas lässt handgerollten Shortfiller zu, und sagt es.') WHERE `name` = 'La Flor de Cano' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 现在的官方页面不再给品牌标日期——1884年和卡诺兄弟来自惯例和早先对该页的阅读——并说全系列（含 Elegidos）为手工短茄芯，中等价位。本图集接受手工短茄芯，并如实说明。') WHERE `name` = 'La Flor de Cano' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. لم تعد الصفحة الرسمية الحالية تؤرّخ العلامة — 1884 والأخوان كانو يأتيان من العرف ومن قراءة سابقة للصفحة — وتقول إنّ المجموعة كلّها، بما فيها Elegidos، ملفوفة يدويًّا بحشوة قصيرة وبسعر متوسّط. يقبل هذا الأطلس الحشوة القصيرة الملفوفة يدويًّا، ويقول ذلك.') WHERE `name` = 'La Flor de Cano' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── La Gloria Cubana ──
UPDATE `brands` SET `factory` = 'Fabrique mère Partagás (Francisco Pérez Germán), San Carlos 806, Centro Habana — selon la presse du métier', `source` = 'habanos.com, page officielle La Gloria Cubana (lue le 14 septembre 2026 : fondée en 1885 ; série Medaille d''Or ; tripe longue, Vuelta Abajo, medium) ; cubancigarwebsite.com « Tobacco and Cigar Production » (Partagás mère de La Gloria Cubana) ; cigaraficionado.com « The New Partagás Factory » (sept.-oct. 2016 : La Gloria Cubana roulée à San Carlos) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'La Gloria Cubana';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Partagás — la Francisco Pérez Germán —, qui a quitté en 2010 le bâtiment jaune d''Industria 520, derrière le Capitole, pour l''ancienne fabrique El Rey del Mundo, San Carlos 806, à Centro Habana ; le vieux bâtiment, promis à un musée puis à un hôtel, s''est partiellement effondré en 2020. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la dit fondée en 1885, peu connue et fidèlement suivie, toute en tripe longue, et retient la présentation de la série Medaille d''Or. Sa fabrique mère est celle de Partagás, comme Bolívar, Ramón Allones et Quai d''Orsay.') WHERE `name` = 'La Gloria Cubana' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Partagás — the Francisco Pérez Germán —, which left the yellow building at Industria 520, behind the Capitol, in 2010 for the former El Rey del Mundo factory at San Carlos 806, Centro Habana; the old building, promised to a museum and then a hotel, partly collapsed in 2020. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page says it was founded in 1885, little known and loyally followed, all long filler, and singles out the presentation of the Medaille d''Or series. Its mother factory is Partagás'', like Bolívar, Ramón Allones and Quai d''Orsay.') WHERE `name` = 'La Gloria Cubana' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Partagás — la Francisco Pérez Germán —, que dejó en 2010 el edificio amarillo de Industria 520, detrás del Capitolio, por la antigua fábrica El Rey del Mundo, San Carlos 806, en Centro Habana; el viejo edificio, prometido a un museo y luego a un hotel, se derrumbó en parte en 2020. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la dice fundada en 1885, poco conocida y fielmente seguida, toda con tripa larga, y destaca la presentación de la serie Medaille d''Or. Su fábrica madre es la de Partagás, como Bolívar, Ramón Allones y Quai d''Orsay.') WHERE `name` = 'La Gloria Cubana' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Partagás — die Francisco Pérez Germán —, die 2010 das gelbe Gebäude an der Industria 520 hinter dem Kapitol für die frühere Fabrik El Rey del Mundo, San Carlos 806, in Centro Habana verließ; das alte Gebäude, erst einem Museum, dann einem Hotel versprochen, stürzte 2020 teilweise ein. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite nennt sie 1885 gegründet, wenig bekannt und treu begleitet, ganz Longfiller, und hebt die Aufmachung der Serie Medaille d''Or hervor. Ihre Mutterfabrik ist die von Partagás, wie bei Bolívar, Ramón Allones und Quai d''Orsay.') WHERE `name` = 'La Gloria Cubana' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是帕塔加斯——即 Francisco Pérez Germán 厂——2010年离开国会大厦后面工业街520号的黄色建筑，迁入中哈瓦那圣卡洛斯街806号原 El Rey del Mundo 厂；老楼先说要做博物馆、后说做酒店，2020年部分坍塌。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它创立于1885年，知名度不高却拥有忠实追随者，全部长茄芯，并特别提到 Medaille d''Or 系列的包装。它的母厂是帕塔加斯厂，与 Bolívar、Ramón Allones、Quai d''Orsay 相同。') WHERE `name` = 'La Gloria Cubana' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Partagás — مصنع فرانسيسكو بيريس خيرمان — الذي غادر سنة 2010 المبنى الأصفر في إندوستريا 520 خلف الكابيتول إلى مصنع El Rey del Mundo السابق، سان كارلوس 806، في سنترو هابانا؛ أمّا المبنى القديم، الموعود بمتحف ثمّ بفندق، فانهار جزئيًّا سنة 2020. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تقول الصفحة الرسمية إنّها تأسّست سنة 1885، قليلة الشهرة ولها أتباع أوفياء، كلّها بحشوة طويلة، وتبرز تقديم سلسلة Medaille d''Or. ومصنعها الأمّ هو مصنع Partagás، مثل Bolívar وRamón Allones وQuai d''Orsay.') WHERE `name` = 'La Gloria Cubana' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Montecristo ──
UPDATE `brands` SET `factory` = 'Fabrique mère H. Upmann (José Martí), Belascoaín, Centro Habana — la marque y est née en 1935, dit la page officielle ; certains modules à La Corona et à Partagás selon la presse du métier', `source` = 'habanos.com, page officielle Montecristo (lue le 14 septembre 2026 : née en 1935 à la fabrique H. Upmann, le lecteur lisant Le Comte de Monte-Cristo ; cinq numéros à l''origine ; Edmundo 2004, Petit Edmundo 2007, Open 2009, Gran Reserva Cosecha 2005 en 2011, Línea 1935, Herederos 2020 ; No. 4 donné comme le havane le plus vendu au monde — affirmation de la maison) ; cubancigarwebsite.com « Tobacco and Cigar Production » (H. Upmann mère de Montecristo) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011 : Montecristo aussi à La Corona) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'Montecristo';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est H. Upmann — la José Martí, ainsi nommée depuis 1960 —, qui a changé plusieurs fois d''adresse et occupe depuis 2011 l''ancien bâtiment Romeo y Julieta de Belascoaín, à Centro Habana. Depuis 2019, Habanos la range dans ses six marques globales, vendues sur tous ses marchés et dans toutes les Casas del Habano. La page officielle la fait naître en 1935 à la fabrique H. Upmann, où le lecteur lisait Dumas aux rouleurs ; c''est encore sa fabrique mère, et la presse du métier note que La Corona et Partagás en roulent aussi.') WHERE `name` = 'Montecristo' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is H. Upmann — the José Martí, so named since 1960 —, which has moved several times and has occupied since 2011 the former Romeo y Julieta building on Belascoaín, Centro Habana. Since 2019 Habanos has placed it among its six global brands, sold in all its markets and in every Casa del Habano. The official page has it born in 1935 at the H. Upmann factory, where the lector read Dumas to the rollers; that is still its mother factory, and the trade press notes that La Corona and Partagás roll it too.') WHERE `name` = 'Montecristo' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es H. Upmann — la José Martí, así llamada desde 1960 —, que cambió varias veces de dirección y ocupa desde 2011 el antiguo edificio Romeo y Julieta de Belascoaín, en Centro Habana. Desde 2019 Habanos la clasifica entre sus seis marcas globales, vendidas en todos sus mercados y en todas las Casas del Habano. La página oficial la hace nacer en 1935 en la fábrica H. Upmann, donde el lector leía a Dumas a los torcedores; sigue siendo su fábrica madre, y la prensa del oficio anota que La Corona y Partagás también la lían.') WHERE `name` = 'Montecristo' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist H. Upmann — die José Martí, so benannt seit 1960 —, die mehrmals umzog und seit 2011 das frühere Romeo-y-Julieta-Gebäude an der Belascoaín in Centro Habana belegt. Seit 2019 zählt Habanos sie zu seinen sechs globalen Marken, die auf allen Märkten und in jeder Casa del Habano verkauft werden. Die offizielle Seite lässt sie 1935 in der Fabrik H. Upmann entstehen, wo der Vorleser den Rollern Dumas vorlas; das ist noch ihre Mutterfabrik, und die Fachpresse vermerkt, dass auch La Corona und Partagás sie rollen.') WHERE `name` = 'Montecristo' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是乌普曼——即1960年起得名的 José Martí 厂——几度搬迁，2011年起占用中哈瓦那贝拉斯科艾因街原罗密欧与朱丽叶厂房。 自2019年起，Habanos 把它列为六个全球品牌之一，在其所有市场和每一家 Casa del Habano 销售。 官方页面说它1935年诞生于乌普曼厂，当时朗读员给卷工念大仲马；那里至今是它的母厂，行业媒体指出 La Corona 和帕塔加斯也卷制它。') WHERE `name` = 'Montecristo' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو H. Upmann — مصنع خوسيه مارتي، بهذا الاسم منذ 1960 — الذي غيّر عنوانه مرارًا ويشغل منذ 2011 مبنى Romeo y Julieta السابق في بيلاسكوين، سنترو هابانا. منذ 2019 تصنّفها Habanos ضمن علاماتها العالمية الستّ، التي تُباع في كلّ أسواقها وفي كلّ Casa del Habano. تجعلها الصفحة الرسمية تولد سنة 1935 في مصنع H. Upmann حيث كان القارئ يقرأ دوما على اللفّافين؛ وما زال مصنعها الأمّ، وتلاحظ الصحافة المتخصّصة أنّ La Corona وPartagás تلفّانها أيضًا.') WHERE `name` = 'Montecristo' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Partagás ──
UPDATE `brands` SET `factory` = 'Fabrique Partagás (Francisco Pérez Germán), San Carlos 806, Centro Habana — depuis 2010, dit la page officielle ; Industria 520 (1845) fermée, effondrée en partie en 2020', `source` = 'habanos.com, page officielle Partagás (lue le 14 septembre 2026 : fabrique créée en 1845 par Jaime Partagás ; longtemps à Industria 520, aujourd''hui à San Carlos 806 ; Serie D No. 4, Lusitanias, 8-9-8, Serie P No. 2 en 2005, Serie E No. 2 et D No. 5 en 2011, Lusitanias Gran Reserva 2013, Serie D No. 6 en 2014, Línea Maduro 2018, humidor Tropicales pour les 175 ans) ; cubancigarwebsite.com « Tobacco and Cigar Production » (fin de l''activité à Industria 520 en 2010 ; ancienne El Rey del Mundo ; effondrement partiel en 2020) ; cigaraficionado.com « The New Partagás Factory » (sept.-oct. 2016 : 209 rouleurs, près de 240 places) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'Partagás';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Partagás — la Francisco Pérez Germán —, qui a quitté en 2010 le bâtiment jaune d''Industria 520, derrière le Capitole, pour l''ancienne fabrique El Rey del Mundo, San Carlos 806, à Centro Habana ; le vieux bâtiment, promis à un musée puis à un hôtel, s''est partiellement effondré en 2020. Depuis 2019, Habanos la range dans ses six marques globales, vendues sur tous ses marchés et dans toutes les Casas del Habano. La page officielle le dit elle-même : longtemps à Industria 520, derrière le Capitole, la fabrique est aujourd''hui à San Carlos 806. La presse du métier date le départ de 2010, comptait 209 rouleurs sur place en 2016 pour près de 240 places, et note que l''ancien bâtiment, où l''on vend encore des cigares, s''est partiellement effondré en 2020.') WHERE `name` = 'Partagás' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Partagás — the Francisco Pérez Germán —, which left the yellow building at Industria 520, behind the Capitol, in 2010 for the former El Rey del Mundo factory at San Carlos 806, Centro Habana; the old building, promised to a museum and then a hotel, partly collapsed in 2020. Since 2019 Habanos has placed it among its six global brands, sold in all its markets and in every Casa del Habano. The official page says it itself: long at Industria 520, behind the Capitol, the factory is today at San Carlos 806. The trade press dates the departure to 2010, counted 209 rollers on site in 2016 for nearly 240 places, and notes that the old building, where cigars are still sold, partly collapsed in 2020.') WHERE `name` = 'Partagás' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Partagás — la Francisco Pérez Germán —, que dejó en 2010 el edificio amarillo de Industria 520, detrás del Capitolio, por la antigua fábrica El Rey del Mundo, San Carlos 806, en Centro Habana; el viejo edificio, prometido a un museo y luego a un hotel, se derrumbó en parte en 2020. Desde 2019 Habanos la clasifica entre sus seis marcas globales, vendidas en todos sus mercados y en todas las Casas del Habano. La página oficial lo dice ella misma: durante mucho tiempo en Industria 520, detrás del Capitolio, la fábrica está hoy en San Carlos 806. La prensa del oficio fecha la salida en 2010, contaba 209 torcedores en 2016 para casi 240 puestos, y anota que el viejo edificio, donde aún se venden puros, se derrumbó en parte en 2020.') WHERE `name` = 'Partagás' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Partagás — die Francisco Pérez Germán —, die 2010 das gelbe Gebäude an der Industria 520 hinter dem Kapitol für die frühere Fabrik El Rey del Mundo, San Carlos 806, in Centro Habana verließ; das alte Gebäude, erst einem Museum, dann einem Hotel versprochen, stürzte 2020 teilweise ein. Seit 2019 zählt Habanos sie zu seinen sechs globalen Marken, die auf allen Märkten und in jeder Casa del Habano verkauft werden. Die offizielle Seite sagt es selbst: lange an der Industria 520 hinter dem Kapitol, liegt die Fabrik heute an der San Carlos 806. Die Fachpresse datiert den Auszug auf 2010, zählte 2016 vor Ort 209 Roller bei fast 240 Plätzen und vermerkt, dass das alte Gebäude, in dem noch Zigarren verkauft werden, 2020 teilweise einstürzte.') WHERE `name` = 'Partagás' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是帕塔加斯——即 Francisco Pérez Germán 厂——2010年离开国会大厦后面工业街520号的黄色建筑，迁入中哈瓦那圣卡洛斯街806号原 El Rey del Mundo 厂；老楼先说要做博物馆、后说做酒店，2020年部分坍塌。 自2019年起，Habanos 把它列为六个全球品牌之一，在其所有市场和每一家 Casa del Habano 销售。 官方页面自己就写了：工厂长期位于国会大厦后面的工业街520号，如今在圣卡洛斯街806号。行业媒体把搬迁定在2010年，2016年现场数到209名卷工、近240个工位，并指出仍在卖雪茄的老楼于2020年部分坍塌。') WHERE `name` = 'Partagás' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Partagás — مصنع فرانسيسكو بيريس خيرمان — الذي غادر سنة 2010 المبنى الأصفر في إندوستريا 520 خلف الكابيتول إلى مصنع El Rey del Mundo السابق، سان كارلوس 806، في سنترو هابانا؛ أمّا المبنى القديم، الموعود بمتحف ثمّ بفندق، فانهار جزئيًّا سنة 2020. منذ 2019 تصنّفها Habanos ضمن علاماتها العالمية الستّ، التي تُباع في كلّ أسواقها وفي كلّ Casa del Habano. تقول الصفحة الرسمية ذلك بنفسها: طويلًا في إندوستريا 520 خلف الكابيتول، والمصنع اليوم في سان كارلوس 806. تؤرّخ الصحافة المتخصّصة الرحيل بسنة 2010، وعدّت 209 لفّافين في الموقع سنة 2016 لنحو 240 مكانًا، وتلاحظ أنّ المبنى القديم، حيث ما زال السيجار يُباع، انهار جزئيًّا سنة 2020.') WHERE `name` = 'Partagás' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Por Larrañaga ──
UPDATE `brands` SET `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane — selon la presse du métier ; tripe longue et tripe courte selon la vitole', `source` = 'habanos.com, page officielle Por Larrañaga (lue le 14 septembre 2026 : fondée en 1834 ; tripe longue et tripe courte selon les vitoles ; Galanes 52 × 120 mm, premier gros module de la marque ; light à medium) ; cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de Por Larrañaga) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011) et « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'Por Larrañaga';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la dit fondée en 1834 et roulée à la main en tripe longue pour certaines vitoles, en tripe courte pour d''autres ; la Galanes, 52 de cépage sur 120 mm, est son premier gros module. L''atlas le dit, comme pour chaque marque qui mêle les deux tripes.') WHERE `name` = 'Por Larrañaga' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page says it was founded in 1834 and is hand-rolled with long filler for some sizes, short filler for others; the Galanes, 52 ring gauge by 120 mm, is its first heavy-gauge size. This atlas says so, as for every brand that mixes the two fillers.') WHERE `name` = 'Por Larrañaga' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la dice fundada en 1834 y liada a mano con tripa larga en algunas vitolas, con tripa corta en otras; la Galanes, cepo 52 por 120 mm, es su primer módulo grueso. El atlas lo dice, como en cada marca que mezcla las dos tripas.') WHERE `name` = 'Por Larrañaga' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite nennt sie 1834 gegründet und von Hand gerollt, mit Longfiller bei manchen Formaten, Shortfiller bei anderen; die Galanes, Ring 52 auf 120 mm, ist ihr erstes dickes Format. Dieser Atlas sagt es, wie bei jeder Marke, die beide Einlagen mischt.') WHERE `name` = 'Por Larrañaga' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它创立于1834年，手工卷制，部分规格长茄芯、部分短茄芯；Galanes（52环径、120毫米）是它第一款粗环径。本图集如实说明，对每个混用两种茄芯的品牌都是如此。') WHERE `name` = 'Por Larrañaga' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تقول الصفحة الرسمية إنّها تأسّست سنة 1834 وتُلفّ يدويًّا بحشوة طويلة في بعض القياسات وقصيرة في أخرى؛ وGalanes، بمحيط 52 على 120 مم، هي قياسها الغليظ الأوّل. يقول هذا الأطلس ذلك، كما مع كلّ علامة تمزج الحشوتين.') WHERE `name` = 'Por Larrañaga' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Punch ──
UPDATE `brands` SET `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane — avec Hoyo de Monterrey depuis 1931, dit la page officielle', `source` = 'habanos.com, page officielle Punch (lue le 14 septembre 2026 : fondée au milieu du XIXe par Manuel López de Juan Valle y Cía pour le marché anglais, du nom de la revue satirique ; en 1931, transfert à la fabrique de Hoyo de Monterrey ; les deux produites à La Corona ; Short de Punch 2019, premier 50 de cépage) ; cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de Punch) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011) et « Cuba Changes Classification of Cigar Brands » (1er août 2019 : haute valeur) ; en.wikipedia.org' WHERE `name` = 'Punch';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, dans le groupe de quatre dit de haute valeur — Bolívar, Punch, Ramón Allones, Trinidad. La page officielle le dit : en 1931, Punch a rejoint la fabrique où l''on faisait Hoyo de Monterrey, et les deux marques sont produites à La Corona. L''atlas l''écrivait chez H. Upmann et Romeo y Julieta, et se corrige. Le Short de Punch de 2019 lui a donné son premier 50 de cépage.') WHERE `name` = 'Punch' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, in the group of four called high-value — Bolívar, Punch, Ramón Allones, Trinidad. The official page says it: in 1931 Punch joined the factory where Hoyo de Monterrey was made, and the two brands are produced at La Corona. This atlas had it at H. Upmann and Romeo y Julieta, and corrects itself. The 2019 Short de Punch gave it its first 50 ring gauge.') WHERE `name` = 'Punch' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, en el grupo de cuatro llamado de alto valor — Bolívar, Punch, Ramón Allones, Trinidad. La página oficial lo dice: en 1931 Punch se unió a la fábrica donde se hacía Hoyo de Monterrey, y las dos marcas se producen en La Corona. El atlas la ponía en H. Upmann y Romeo y Julieta, y se corrige. El Short de Punch de 2019 le dio su primer cepo 50.') WHERE `name` = 'Punch' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, in der Vierergruppe, die hochwertig genannt wird — Bolívar, Punch, Ramón Allones, Trinidad. Die offizielle Seite sagt es: 1931 kam Punch in die Fabrik, in der Hoyo de Monterrey gemacht wurde, und beide Marken werden bei La Corona produziert. Dieser Atlas hatte sie bei H. Upmann und Romeo y Julieta und korrigiert sich. Der Short de Punch von 2019 gab ihr ihren ersten Ring 50.') WHERE `name` = 'Punch' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入二十一个组合品牌，属于所谓高价值的四个品牌一组——Bolívar、Punch、Ramón Allones、Trinidad。 官方页面写明：1931年 Punch 并入生产 Hoyo de Monterrey 的工厂，两个品牌都在 La Corona 生产。本图集原先写在乌普曼和罗密欧与朱丽叶厂，予以更正。2019年的 Short de Punch 给了它首个50环径。') WHERE `name` = 'Punch' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، في مجموعة الأربع المسمّاة عالية القيمة — Bolívar وPunch وRamón Allones وTrinidad. تقول الصفحة الرسمية ذلك: سنة 1931 انضمّت Punch إلى المصنع الذي كانت تُصنع فيه Hoyo de Monterrey، والعلامتان تُنتجان في La Corona. وكان هذا الأطلس يضعها عند H. Upmann وRomeo y Julieta، ويصحّح نفسه. وأعطاها Short de Punch سنة 2019 محيطها 50 الأوّل.') WHERE `name` = 'Punch' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Quai d'Orsay ──
UPDATE `brands` SET `factory` = 'Fabrique mère Partagás (Francisco Pérez Germán), San Carlos 806, Centro Habana — selon la presse du métier', `source` = 'habanos.com, page officielle Quai d''Orsay (lue le 14 septembre 2026 : créée en 1973 par Cubatabaco pour la Seita ; quarante ans réservée au marché français ; nouvelle bague et distribution internationale avec No. 50 et No. 54, avec la Coronas Claro ; Secreto Cubano, édition régionale France 2016 ; tripe longue, light) ; cubancigarwebsite.com « Tobacco and Cigar Production » (Partagás mère de Quai d''Orsay) ; cigaraficionado.com « The New Partagás Factory » (sept.-oct. 2016) et « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Quai d''Orsay';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Partagás — la Francisco Pérez Germán —, qui a quitté en 2010 le bâtiment jaune d''Industria 520, derrière le Capitole, pour l''ancienne fabrique El Rey del Mundo, San Carlos 806, à Centro Habana ; le vieux bâtiment, promis à un musée puis à un hôtel, s''est partiellement effondré en 2020. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle raconte sa sortie du marché français : créée en 1973 par Cubatabaco à la demande de la Seita, dont les bureaux étaient sur le quai, elle est restée quarante ans une marque pour connaisseurs français, puis a reçu une nouvelle bague — La Havane et Cuba inscrites — et deux vitoles, No. 50 et No. 54, distribuées sur tous les marchés avec la Coronas Claro.') WHERE `name` = 'Quai d''Orsay' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Partagás — the Francisco Pérez Germán —, which left the yellow building at Industria 520, behind the Capitol, in 2010 for the former El Rey del Mundo factory at San Carlos 806, Centro Habana; the old building, promised to a museum and then a hotel, partly collapsed in 2020. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page tells of its exit from the French market: created in 1973 by Cubatabaco at the request of Seita, whose offices were on the quay, it stayed forty years a brand for French connoisseurs, then received a new band — Havana and Cuba inscribed — and two sizes, No. 50 and No. 54, distributed on all markets with the Coronas Claro.') WHERE `name` = 'Quai d''Orsay' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Partagás — la Francisco Pérez Germán —, que dejó en 2010 el edificio amarillo de Industria 520, detrás del Capitolio, por la antigua fábrica El Rey del Mundo, San Carlos 806, en Centro Habana; el viejo edificio, prometido a un museo y luego a un hotel, se derrumbó en parte en 2020. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial cuenta su salida del mercado francés: creada en 1973 por Cubatabaco a petición de la Seita, cuyas oficinas estaban en el muelle, siguió cuarenta años como marca para entendidos franceses, y luego recibió una nueva anilla — La Habana y Cuba inscritas — y dos vitolas, No. 50 y No. 54, distribuidas en todos los mercados con la Coronas Claro.') WHERE `name` = 'Quai d''Orsay' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Partagás — die Francisco Pérez Germán —, die 2010 das gelbe Gebäude an der Industria 520 hinter dem Kapitol für die frühere Fabrik El Rey del Mundo, San Carlos 806, in Centro Habana verließ; das alte Gebäude, erst einem Museum, dann einem Hotel versprochen, stürzte 2020 teilweise ein. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite erzählt ihren Weg aus dem französischen Markt: 1973 von Cubatabaco auf Wunsch der Seita geschaffen, deren Büros am Quai lagen, blieb sie vierzig Jahre eine Marke für französische Kenner, erhielt dann eine neue Bauchbinde — Havanna und Kuba eingeschrieben — und zwei Formate, No. 50 und No. 54, auf allen Märkten vertrieben mit der Coronas Claro.') WHERE `name` = 'Quai d''Orsay' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是帕塔加斯——即 Francisco Pérez Germán 厂——2010年离开国会大厦后面工业街520号的黄色建筑，迁入中哈瓦那圣卡洛斯街806号原 El Rey del Mundo 厂；老楼先说要做博物馆、后说做酒店，2020年部分坍塌。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面讲述它走出法国市场的经过：1973年由 Cubatabaco 应 Seita 之请创立——Seita 的办公室就在那条河岸——四十年间只是法国行家的品牌，随后换了新茄标（印上哈瓦那与古巴），并推出 No. 50 和 No. 54 两款，连同 Coronas Claro 在所有市场发售。') WHERE `name` = 'Quai d''Orsay' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Partagás — مصنع فرانسيسكو بيريس خيرمان — الذي غادر سنة 2010 المبنى الأصفر في إندوستريا 520 خلف الكابيتول إلى مصنع El Rey del Mundo السابق، سان كارلوس 806، في سنترو هابانا؛ أمّا المبنى القديم، الموعود بمتحف ثمّ بفندق، فانهار جزئيًّا سنة 2020. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تروي الصفحة الرسمية خروجها من السوق الفرنسية: أنشأتها Cubatabaco سنة 1973 بطلب من Seita التي كانت مكاتبها على الرصيف، وبقيت أربعين عامًا علامة للعارفين الفرنسيين، ثمّ نالت حلقة جديدة — نُقش عليها هافانا وكوبا — وقياسين، No. 50 وNo. 54، يُوزَّعان في كلّ الأسواق مع Coronas Claro.') WHERE `name` = 'Quai d''Orsay' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Quintero ──
UPDATE `brands` SET `factory` = 'Fabrique mère de Cienfuegos (vers 1925), selon la presse du métier ; tripe courte roulée main, tabac de Vuelta Abajo', `source` = 'habanos.com, page officielle Quintero (lue le 14 septembre 2026 : Agustín Quintero installé à Cienfuegos ; l''une des rares marques non nées à La Havane ; tripe courte roulée main, tabac de Vuelta Abajo, medium, prix accessible ; pas d''année — 1924 vient de l''usage) ; cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique provinciale de Cienfuegos, vers 1925, mère de Quintero) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019 : marque de volume) ; en.wikipedia.org' WHERE `name` = 'Quintero';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est celle de Cienfuegos, ouverte vers 1925, là où la marque est née — l''une des rares du portefeuille qui ne soit pas havanaise. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle ne date pas la marque — 1924 vient de l''usage — mais la dit née hors de La Havane, à Cienfuegos, la perle du Sud, et toute roulée à la main en tripe courte, avec du tabac de Vuelta Abajo ; l''atlas l''écrivait chez El Rey del Mundo, et se corrige.') WHERE `name` = 'Quintero' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is the Cienfuegos factory, opened around 1925, where the brand was born — one of the few in the portfolio that is not from Havana. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page does not date the brand — 1924 comes from usage — but says it was born outside Havana, in Cienfuegos, the pearl of the South, and is all hand-rolled short filler, with Vuelta Abajo tobacco; this atlas had it at El Rey del Mundo, and corrects itself.') WHERE `name` = 'Quintero' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es la de Cienfuegos, abierta hacia 1925, donde nació la marca — una de las pocas del portafolio que no es habanera. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial no fecha la marca — 1924 viene del uso — pero la dice nacida fuera de La Habana, en Cienfuegos, la perla del Sur, y toda liada a mano con tripa corta, con tabaco de Vuelta Abajo; el atlas la ponía en El Rey del Mundo, y se corrige.') WHERE `name` = 'Quintero' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist die von Cienfuegos, um 1925 eröffnet, wo die Marke entstand — eine der wenigen im Portfolio, die nicht aus Havanna ist. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite datiert die Marke nicht — 1924 stammt aus dem Gebrauch —, nennt sie aber außerhalb Havannas entstanden, in Cienfuegos, der Perle des Südens, und ganz handgerollten Shortfiller mit Vuelta-Abajo-Tabak; dieser Atlas hatte sie bei El Rey del Mundo und korrigiert sich.') WHERE `name` = 'Quintero' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是西恩富戈斯厂，约1925年开办，品牌就在那里诞生——是产品组合里少数不属于哈瓦那的品牌之一。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面没有给品牌标日期——1924年来自惯例——但说它诞生在哈瓦那之外的西恩富戈斯，南方的明珠，全部为手工短茄芯，用下维尔塔烟叶；本图集原先写在 El Rey del Mundo，予以更正。') WHERE `name` = 'Quintero' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو مصنع سيينفويغوس، المفتوح نحو 1925، حيث وُلدت العلامة — وهي من القلائل في المحفظة التي ليست من هافانا. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. لا تؤرّخ الصفحة الرسمية العلامة — 1924 من العرف — لكنّها تقول إنّها وُلدت خارج هافانا، في سيينفويغوس لؤلؤة الجنوب، وإنّها كلّها ملفوفة يدويًّا بحشوة قصيرة من تبغ فويلتا أباخو؛ وكان هذا الأطلس يضعها عند El Rey del Mundo، ويصحّح نفسه.') WHERE `name` = 'Quintero' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Rafael González ──
UPDATE `brands` SET `factory` = 'Fabrique mère non nommée par Habanos ni par la presse du métier consultée ; roulée à Cuba sous le régime des fabriques mères', `source` = 'habanos.com, page officielle Rafael González (lue le 14 septembre 2026 : créée dans les années 1930 ; vitole de fabrique Cervantes, d''abord appelée Lonsdale ; l''avis imprimé dans le couvercle — fumer dans le mois suivant l''expédition ou laisser mûrir un an ; tripe longue sauf une vitole en tripe courte ; light) ; l''ancienne lecture donnait 1928 ; cubancigarwebsite.com et cigaraficionado.com (2011, 2016) ne nomment pas sa fabrique mère ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)', `founded` = '1928 (usage) ou années 1930 (Habanos) — La Havane' WHERE `name` = 'Rafael González';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Aucune source consultée — ni Habanos, ni la presse du métier — ne nomme sa fabrique mère ; la fiche le dit plutôt que de choisir. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la date des années 1930 — la fiche garde 1928, l''année de l''usage, et écrit les deux —, rappelle que sa vitole de fabrique s''appelle Cervantes et fut d''abord une Lonsdale, du nom du lord, et dit la gamme en tripe longue à une exception près, en tripe courte.') WHERE `name` = 'Rafael González' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. No source consulted — neither Habanos nor the trade press — names its mother factory; the entry says so rather than choosing. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it to the 1930s — the entry keeps 1928, the year in use, and writes both —, recalls that its factory size is called Cervantes and was first a Lonsdale, after the lord, and says the range is long filler with one exception, short filler.') WHERE `name` = 'Rafael González' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Ninguna fuente consultada — ni Habanos, ni la prensa del oficio — nombra su fábrica madre; la ficha lo dice en vez de elegir. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la fecha en los años treinta — la ficha conserva 1928, el año en uso, y escribe las dos —, recuerda que su vitola de galera se llama Cervantes y fue primero una Lonsdale, por el lord, y dice la gama con tripa larga salvo una excepción, con tripa corta.') WHERE `name` = 'Rafael González' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Keine befragte Quelle — weder Habanos noch die Fachpresse — nennt ihre Mutterfabrik; der Eintrag sagt es, statt zu wählen. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie in die 1930er Jahre — der Eintrag behält 1928, das gebräuchliche Jahr, und schreibt beide —, erinnert daran, dass ihr Fabrikformat Cervantes heißt und zuerst eine Lonsdale war, nach dem Lord, und nennt die Palette Longfiller mit einer Ausnahme, Shortfiller.') WHERE `name` = 'Rafael González' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 查阅的来源——无论 Habanos 还是行业媒体——都没有点名它的母厂；词条如实说明，而不是自行挑选。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把它定在1930年代——词条保留通行的1928年，两者都写——提到它的厂内规格名为 Cervantes，最初叫 Lonsdale，以那位勋爵命名；系列为长茄芯，仅一款例外为短茄芯。') WHERE `name` = 'Rafael González' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا يسمّي أيّ مصدر راجعناه — لا Habanos ولا الصحافة المتخصّصة — مصنعها الأمّ؛ وتقول البطاقة ذلك بدل أن تختار. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤرّخها الصفحة الرسمية في الثلاثينيات — تحتفظ البطاقة بـ1928، السنة المتداولة، وتكتب الاثنتين — وتذكّر بأنّ قياس مصنعها يُسمّى Cervantes وكان أوّلًا Lonsdale على اسم اللورد، وتقول إنّ المجموعة بحشوة طويلة باستثناء واحد بحشوة قصيرة.') WHERE `name` = 'Rafael González' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Ramón Allones ──
UPDATE `brands` SET `factory` = 'Fabrique mère Partagás (Francisco Pérez Germán), San Carlos 806, Centro Habana — selon la presse du métier', `source` = 'habanos.com, page officielle Ramón Allones (lue le 14 septembre 2026 : fondée en 1837 ; premier à décorer ses boîtes d''étiquettes et de l''emblème de la marque ; éditions régionales ; tripe longue, full ; Gigantes, Allones Specially Selected, Allones No. 2 édition limitée 2019) ; cubancigarwebsite.com « Tobacco and Cigar Production » (Partagás mère de Ramón Allones) ; cigaraficionado.com « The New Partagás Factory » (sept.-oct. 2016) et « Cuba Changes Classification of Cigar Brands » (1er août 2019 : haute valeur) ; en.wikipedia.org' WHERE `name` = 'Ramón Allones';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Partagás — la Francisco Pérez Germán —, qui a quitté en 2010 le bâtiment jaune d''Industria 520, derrière le Capitole, pour l''ancienne fabrique El Rey del Mundo, San Carlos 806, à Centro Habana ; le vieux bâtiment, promis à un musée puis à un hôtel, s''est partiellement effondré en 2020. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, dans le groupe de quatre dit de haute valeur — Bolívar, Punch, Ramón Allones, Trinidad. La page officielle la dit fondée en 1837, parmi les plus anciennes encore en production, et première à avoir habillé ses boîtes d''étiquettes et de son emblème ; tout en tripe longue, de goût plein, Gigantes et Allones Specially Selected en tête. Sa fabrique mère est celle de Partagás.') WHERE `name` = 'Ramón Allones' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Partagás — the Francisco Pérez Germán —, which left the yellow building at Industria 520, behind the Capitol, in 2010 for the former El Rey del Mundo factory at San Carlos 806, Centro Habana; the old building, promised to a museum and then a hotel, partly collapsed in 2020. Since 2019 Habanos has placed it among its twenty-one portfolio brands, in the group of four called high-value — Bolívar, Punch, Ramón Allones, Trinidad. The official page says it was founded in 1837, among the oldest still in production, and the first to dress its boxes with labels and its emblem; all long filler, full in taste, Gigantes and Allones Specially Selected first. Its mother factory is Partagás''.') WHERE `name` = 'Ramón Allones' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Partagás — la Francisco Pérez Germán —, que dejó en 2010 el edificio amarillo de Industria 520, detrás del Capitolio, por la antigua fábrica El Rey del Mundo, San Carlos 806, en Centro Habana; el viejo edificio, prometido a un museo y luego a un hotel, se derrumbó en parte en 2020. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, en el grupo de cuatro llamado de alto valor — Bolívar, Punch, Ramón Allones, Trinidad. La página oficial la dice fundada en 1837, entre las más antiguas aún en producción, y la primera en vestir sus cajas con etiquetas y su emblema; toda con tripa larga, de sabor pleno, Gigantes y Allones Specially Selected a la cabeza. Su fábrica madre es la de Partagás.') WHERE `name` = 'Ramón Allones' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Partagás — die Francisco Pérez Germán —, die 2010 das gelbe Gebäude an der Industria 520 hinter dem Kapitol für die frühere Fabrik El Rey del Mundo, San Carlos 806, in Centro Habana verließ; das alte Gebäude, erst einem Museum, dann einem Hotel versprochen, stürzte 2020 teilweise ein. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, in der Vierergruppe, die hochwertig genannt wird — Bolívar, Punch, Ramón Allones, Trinidad. Die offizielle Seite nennt sie 1837 gegründet, unter den ältesten noch produzierten, und die erste, die ihre Kisten mit Etiketten und ihrem Emblem schmückte; ganz Longfiller, voll im Geschmack, Gigantes und Allones Specially Selected voran. Ihre Mutterfabrik ist die von Partagás.') WHERE `name` = 'Ramón Allones' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是帕塔加斯——即 Francisco Pérez Germán 厂——2010年离开国会大厦后面工业街520号的黄色建筑，迁入中哈瓦那圣卡洛斯街806号原 El Rey del Mundo 厂；老楼先说要做博物馆、后说做酒店，2020年部分坍塌。 自2019年起，Habanos 把它列入二十一个组合品牌，属于所谓高价值的四个品牌一组——Bolívar、Punch、Ramón Allones、Trinidad。 官方页面说它创立于1837年，属于仍在生产的老品牌之列，并率先在雪茄盒上贴标签和印徽记；全部长茄芯，口味饱满，以 Gigantes 和 Allones Specially Selected 为代表。它的母厂是帕塔加斯厂。') WHERE `name` = 'Ramón Allones' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Partagás — مصنع فرانسيسكو بيريس خيرمان — الذي غادر سنة 2010 المبنى الأصفر في إندوستريا 520 خلف الكابيتول إلى مصنع El Rey del Mundo السابق، سان كارلوس 806، في سنترو هابانا؛ أمّا المبنى القديم، الموعود بمتحف ثمّ بفندق، فانهار جزئيًّا سنة 2020. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، في مجموعة الأربع المسمّاة عالية القيمة — Bolívar وPunch وRamón Allones وTrinidad. تقول الصفحة الرسمية إنّها تأسّست سنة 1837، من أقدم العلامات التي ما زالت تُنتَج، وأنّها كانت السبّاقة إلى تزيين علبها بالملصقات وشعارها؛ كلّها بحشوة طويلة، مكتملة الطعم، وفي المقدّمة Gigantes وAllones Specially Selected. ومصنعها الأمّ هو مصنع Partagás.') WHERE `name` = 'Ramón Allones' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Romeo y Julieta ──
UPDATE `brands` SET `factory` = 'Fabrique mère Romeo y Julieta (Briones Montoto) : Belascoaín 852 jusqu''en 2011, cédée à H. Upmann ; depuis la fin des années 2010, l''ancienne Carlos Baliño rebaptisée, selon la presse du métier', `source` = 'habanos.com, page officielle Romeo y Julieta (lue le 14 septembre 2026 : créée en 1875 ; Pepín Rodríguez et la bague ; Churchill en visite en 1946 ; Short Churchills 2006, Wide Churchills 2010 — premier 55 de cépage —, Petit Churchills 2012, Petit Royales 2017, Línea de Oro pour les 145 ans ; la page ne nomme pas de fabrique) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011 : Belascoaín 852, partagée avec H. Upmann) ; cubancigarwebsite.com « Tobacco and Cigar Production » (bâtiment cédé à H. Upmann en 2011 ; l''ancienne El Rey del Mundo / Carlos Baliño rebaptisée Romeo y Julieta à la fin des années 2010, mère d''El Rey del Mundo et Saint Luis Rey) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019) ; en.wikipedia.org' WHERE `name` = 'Romeo y Julieta';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Romeo y Julieta : le bâtiment historique de Belascoaín a été cédé à H. Upmann en 2011, et c''est l''ancienne fabrique Carlos Baliño — celle qui portait le nom d''El Rey del Mundo —, rebaptisée, qui tient ce rôle depuis la fin des années 2010, selon la presse spécialisée. Depuis 2019, Habanos la range dans ses six marques globales, vendues sur tous ses marchés et dans toutes les Casas del Habano. La presse du métier de 2011 la voyait partager le bâtiment de Belascoaín avec H. Upmann, qui venait d''y emménager ; le site de référence des havanes dit ensuite la marque sans maison jusqu''à ce que l''ancienne fabrique Carlos Baliño prenne son nom, à la fin des années 2010. Habanos, lui, ne nomme pas de fabrique. La page officielle retient Pepín Rodríguez et la bague, Churchill en 1946, la Wide Churchills de 2010 qui inaugura le 55 de cépage, et la Línea de Oro des 145 ans.') WHERE `name` = 'Romeo y Julieta' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Romeo y Julieta: the historic Belascoaín building was ceded to H. Upmann in 2011, and it is the former Carlos Baliño factory — the one that bore the El Rey del Mundo name —, renamed, that has held the role since the late 2010s, according to the specialist press. Since 2019 Habanos has placed it among its six global brands, sold in all its markets and in every Casa del Habano. The 2011 trade press saw it sharing the Belascoaín building with H. Upmann, which had just moved in; the Havana reference site then says the brand was homeless until the former Carlos Baliño factory took its name, in the late 2010s. Habanos itself names no factory. The official page keeps Pepín Rodríguez and the band, Churchill in 1946, the 2010 Wide Churchills that opened the 55 ring gauge, and the Línea de Oro of the 145th year.') WHERE `name` = 'Romeo y Julieta' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Romeo y Julieta: el edificio histórico de Belascoaín se cedió a H. Upmann en 2011, y es la antigua fábrica Carlos Baliño — la que llevaba el nombre de El Rey del Mundo —, rebautizada, la que cumple ese papel desde finales de los años 2010, según la prensa especializada. Desde 2019 Habanos la clasifica entre sus seis marcas globales, vendidas en todos sus mercados y en todas las Casas del Habano. La prensa del oficio de 2011 la veía compartir el edificio de Belascoaín con H. Upmann, que acababa de instalarse; el sitio de referencia de los habanos dice luego la marca sin casa hasta que la antigua fábrica Carlos Baliño tomó su nombre, a finales de los años 2010. Habanos, por su parte, no nombra fábrica. La página oficial retiene a Pepín Rodríguez y la anilla, Churchill en 1946, la Wide Churchills de 2010 que inauguró el cepo 55, y la Línea de Oro de los 145 años.') WHERE `name` = 'Romeo y Julieta' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Romeo y Julieta: Das historische Gebäude an der Belascoaín wurde 2011 an H. Upmann abgetreten, und die frühere Fabrik Carlos Baliño — die den Namen El Rey del Mundo trug —, umbenannt, hat diese Rolle seit Ende der 2010er Jahre inne, laut Fachpresse. Seit 2019 zählt Habanos sie zu seinen sechs globalen Marken, die auf allen Märkten und in jeder Casa del Habano verkauft werden. Die Fachpresse von 2011 sah sie das Gebäude an der Belascoaín mit H. Upmann teilen, das gerade eingezogen war; die Referenzseite der Havannas nennt die Marke danach heimatlos, bis die frühere Fabrik Carlos Baliño Ende der 2010er Jahre ihren Namen annahm. Habanos selbst nennt keine Fabrik. Die offizielle Seite behält Pepín Rodríguez und die Bauchbinde, Churchill 1946, die Wide Churchills von 2010, die den Ring 55 eröffnete, und die Línea de Oro zum 145. Jahr.') WHERE `name` = 'Romeo y Julieta' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是罗密欧与朱丽叶：贝拉斯科艾因街的历史厂房2011年让给了乌普曼，据专业媒体，自2010年代末起由原 Carlos Baliño 厂——曾以 El Rey del Mundo 为名——更名后担任这一角色。 自2019年起，Habanos 把它列为六个全球品牌之一，在其所有市场和每一家 Casa del Habano 销售。 2011年的行业媒体看到它与刚搬进来的乌普曼共用贝拉斯科艾因街的厂房；哈瓦那雪茄的参考网站随后说，品牌一度无家可归，直到2010年代末原 Carlos Baliño 厂改用它的名字。Habanos 自己没有点名工厂。官方页面记下佩平·罗德里格斯与茄标、1946年的丘吉尔、2010年开创55环径的 Wide Churchills，以及一百四十五周年的 Línea de Oro。') WHERE `name` = 'Romeo y Julieta' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Romeo y Julieta: تنازل المبنى التاريخي في بيلاسكوين لـH. Upmann سنة 2011، ومصنع كارلوس بالينيو السابق — الذي كان يحمل اسم El Rey del Mundo — هو الذي يؤدّي هذا الدور بعد إعادة تسميته منذ أواخر عقد 2010، بحسب الصحافة المتخصّصة. منذ 2019 تصنّفها Habanos ضمن علاماتها العالمية الستّ، التي تُباع في كلّ أسواقها وفي كلّ Casa del Habano. رأتها الصحافة المتخصّصة سنة 2011 تتقاسم مبنى بيلاسكوين مع H. Upmann التي كانت قد انتقلت إليه للتوّ؛ ثمّ يقول الموقع المرجعي للسيجار الهافاني إنّ العلامة بقيت بلا دار حتّى اتّخذ مصنع كارلوس بالينيو السابق اسمها في أواخر عقد 2010. أمّا Habanos فلا تسمّي مصنعًا. وتحتفظ الصفحة الرسمية ببيبين رودريغيس والحلقة، وتشرشل سنة 1946، وWide Churchills سنة 2010 التي افتتحت محيط 55، وLínea de Oro للسنة الخامسة والأربعين بعد المئة.') WHERE `name` = 'Romeo y Julieta' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Saint Luis Rey ──
UPDATE `brands` SET `factory` = 'Fabrique mère Romeo y Julieta (ex-Carlos Baliño), La Havane — selon la presse du métier', `source` = 'habanos.com, page officielle Saint Luis Rey (lue le 14 septembre 2026 : fondée avant la Seconde Guerre mondiale ; nom rapporté au district de San Luis plutôt qu''au roman de Thornton Wilder ; goûts intenses ; éditions régionales) ; en.wikipedia.org (1938) ; cubancigarwebsite.com « Tobacco and Cigar Production » (fabrique Romeo y Julieta, ex-Carlos Baliño, mère de Saint Luis Rey) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Saint Luis Rey';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Romeo y Julieta : le bâtiment historique de Belascoaín a été cédé à H. Upmann en 2011, et c''est l''ancienne fabrique Carlos Baliño — celle qui portait le nom d''El Rey del Mundo —, rebaptisée, qui tient ce rôle depuis la fin des années 2010, selon la presse spécialisée. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle ne la date que d''avant la Seconde Guerre mondiale — 1938 ou 1940 selon les sources, la fiche garde 1940 et l''écrit — et préfère au roman de Thornton Wilder l''explication du nom par San Luis, le district de la Vuelta Abajo réputé pour ses capes. Sa fabrique mère, selon la presse du métier, est celle de Romeo y Julieta.') WHERE `name` = 'Saint Luis Rey' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Romeo y Julieta: the historic Belascoaín building was ceded to H. Upmann in 2011, and it is the former Carlos Baliño factory — the one that bore the El Rey del Mundo name —, renamed, that has held the role since the late 2010s, according to the specialist press. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page dates it only to before the Second World War — 1938 or 1940 depending on the source, the entry keeps 1940 and says so — and prefers to Thornton Wilder''s novel the explanation of the name by San Luis, the Vuelta Abajo district renowned for its wrappers. Its mother factory, according to the trade press, is Romeo y Julieta''s.') WHERE `name` = 'Saint Luis Rey' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Romeo y Julieta: el edificio histórico de Belascoaín se cedió a H. Upmann en 2011, y es la antigua fábrica Carlos Baliño — la que llevaba el nombre de El Rey del Mundo —, rebautizada, la que cumple ese papel desde finales de los años 2010, según la prensa especializada. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial solo la fecha antes de la Segunda Guerra Mundial — 1938 o 1940 según las fuentes, la ficha conserva 1940 y lo escribe — y prefiere a la novela de Thornton Wilder la explicación del nombre por San Luis, el distrito de la Vuelta Abajo reputado por sus capas. Su fábrica madre, según la prensa del oficio, es la de Romeo y Julieta.') WHERE `name` = 'Saint Luis Rey' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Romeo y Julieta: Das historische Gebäude an der Belascoaín wurde 2011 an H. Upmann abgetreten, und die frühere Fabrik Carlos Baliño — die den Namen El Rey del Mundo trug —, umbenannt, hat diese Rolle seit Ende der 2010er Jahre inne, laut Fachpresse. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite datiert sie nur auf vor dem Zweiten Weltkrieg — 1938 oder 1940 je nach Quelle, der Eintrag behält 1940 und schreibt es — und zieht dem Roman Thornton Wilders die Erklärung des Namens durch San Luis vor, den für seine Deckblätter bekannten Distrikt der Vuelta Abajo. Ihre Mutterfabrik ist laut Fachpresse die von Romeo y Julieta.') WHERE `name` = 'Saint Luis Rey' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是罗密欧与朱丽叶：贝拉斯科艾因街的历史厂房2011年让给了乌普曼，据专业媒体，自2010年代末起由原 Carlos Baliño 厂——曾以 El Rey del Mundo 为名——更名后担任这一角色。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面只把它定在第二次世界大战之前——依来源为1938或1940年，词条保留1940并如实写明——并且相比桑顿·怀尔德的小说，更倾向于用下维尔塔以茄衣闻名的圣路易斯区来解释这个名字。据行业媒体，它的母厂是罗密欧与朱丽叶厂。') WHERE `name` = 'Saint Luis Rey' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Romeo y Julieta: تنازل المبنى التاريخي في بيلاسكوين لـH. Upmann سنة 2011، ومصنع كارلوس بالينيو السابق — الذي كان يحمل اسم El Rey del Mundo — هو الذي يؤدّي هذا الدور بعد إعادة تسميته منذ أواخر عقد 2010، بحسب الصحافة المتخصّصة. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. لا تؤرّخها الصفحة الرسمية إلّا بما قبل الحرب العالمية الثانية — 1938 أو 1940 بحسب المصادر، وتحتفظ البطاقة بـ1940 وتكتب ذلك — وتفضّل على رواية ثورنتون وايلدر تفسير الاسم بسان لويس، مقاطعة فويلتا أباخو المعروفة بأغلفتها. ومصنعها الأمّ، بحسب الصحافة المتخصّصة، هو مصنع Romeo y Julieta.') WHERE `name` = 'Saint Luis Rey' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── San Cristóbal de La Habana ──
UPDATE `brands` SET `factory` = 'Fabrique mère La Corona (Miguel Fernández Roig), Cerro, La Havane — selon la presse du métier ; marque réservée au réseau La Casa del Habano, dit la page officielle', `source` = 'habanos.com, page officielle San Cristóbal de la Habana (lue le 14 septembre 2026 : lancée en 1999 ; El Morro, La Fuerza, La Punta, El Príncipe ; Mercaderes, Oficios, Muralla en 2004 ; réservée au réseau La Casa del Habano ; 20 Aniversario en 2019 ; tripe longue, light à medium) ; cubancigarwebsite.com « Tobacco and Cigar Production » (La Corona mère de San Cristóbal) ; cigaraficionado.com « Havana''s Cigar Factories » (nov.-déc. 2011) et « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'San Cristóbal de La Habana';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est La Corona — la Miguel Fernández Roig —, née en 1889, installée depuis 2000 dans une ancienne fabrique de cigarettes du Cerro, l''une des plus grandes de La Havane. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle la dit lancée en 1999 pour l''histoire de la ville, avec quatre vitoles aux noms de forteresses — El Morro, La Fuerza, La Punta, El Príncipe —, élargie en 2004 aux rues de la vieille ville, et réservée au réseau des Casas del Habano ; ses 20 ans, en 2019, dans le cadre des 500 ans de La Havane. Sa fabrique mère est La Corona.') WHERE `name` = 'San Cristóbal de La Habana' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is La Corona — the Miguel Fernández Roig —, founded in 1889, housed since 2000 in a former cigarette factory in Cerro, one of Havana''s largest. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page says it was launched in 1999 for the city''s history, with four sizes named after fortresses — El Morro, La Fuerza, La Punta, El Príncipe —, widened in 2004 to the streets of the old town, and reserved for the Casas del Habano network; its 20th year, in 2019, within Havana''s 500th. Its mother factory is La Corona.') WHERE `name` = 'San Cristóbal de La Habana' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es La Corona — la Miguel Fernández Roig —, fundada en 1889, instalada desde 2000 en una antigua fábrica de cigarrillos del Cerro, una de las mayores de La Habana. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial la dice lanzada en 1999 por la historia de la ciudad, con cuatro vitolas con nombres de fortalezas — El Morro, La Fuerza, La Punta, El Príncipe —, ampliada en 2004 a las calles de la ciudad vieja, y reservada a la red de las Casas del Habano; sus 20 años, en 2019, en el marco de los 500 de La Habana. Su fábrica madre es La Corona.') WHERE `name` = 'San Cristóbal de La Habana' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist La Corona — die Miguel Fernández Roig —, 1889 gegründet, seit 2000 in einer früheren Zigarettenfabrik im Cerro untergebracht, eine der größten Havannas. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite nennt sie 1999 für die Geschichte der Stadt lanciert, mit vier nach Festungen benannten Formaten — El Morro, La Fuerza, La Punta, El Príncipe —, 2004 um die Straßen der Altstadt erweitert und dem Netz der Casas del Habano vorbehalten; ihr 20. Jahr 2019 im Rahmen der 500 Jahre Havannas. Ihre Mutterfabrik ist La Corona.') WHERE `name` = 'San Cristóbal de La Habana' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是 La Corona——即 Miguel Fernández Roig 厂——建于1889年，2000年起设在塞罗区一座原卷烟厂内，是哈瓦那规模较大的工厂之一。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面说它1999年为纪念这座城市的历史而推出，四款规格以要塞命名——El Morro、La Fuerza、La Punta、El Príncipe——2004年扩展到老城街道之名，并且专供 Casas del Habano 网络；2019年在哈瓦那建城五百年之际满二十周年。它的母厂是 La Corona。') WHERE `name` = 'San Cristóbal de La Habana' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو La Corona — مصنع ميغيل فرنانديس رويغ — المؤسَّس سنة 1889، والمقيم منذ 2000 في مصنع سجائر سابق في حيّ سيرو، وهو من كبار مصانع هافانا. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تقول الصفحة الرسمية إنّها أُطلقت سنة 1999 لتاريخ المدينة، بأربعة قياسات بأسماء قلاع — El Morro وLa Fuerza وLa Punta وEl Príncipe — ووُسّعت سنة 2004 إلى شوارع المدينة القديمة، ومخصّصة لشبكة Casas del Habano؛ وعامها العشرون سنة 2019 في إطار خمسمئة عام لهافانا. ومصنعها الأمّ هو La Corona.') WHERE `name` = 'San Cristóbal de La Habana' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Sancho Panza ──
UPDATE `brands` SET `factory` = 'Fabrique mère non nommée par Habanos ni par la presse du métier consultée ; roulée à Cuba sous le régime des fabriques mères', `source` = 'habanos.com, page officielle Sancho Panza (lue le 14 septembre 2026 : nom tiré du Quichotte ; premier enregistrement en 1848 ; trois havanes aujourd''hui dont le Molino, nom de fabrique Cervantes ; tripe longue, medium) ; en.wikipedia.org (Emilio Ohmstedt) ; cubancigarwebsite.com et cigaraficionado.com (2011, 2016) ne nomment pas sa fabrique mère ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Sancho Panza';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Aucune source consultée — ni Habanos, ni la presse du métier — ne nomme sa fabrique mère ; la fiche le dit plutôt que de choisir. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle confirme le premier enregistrement en 1848 et une gamme réduite aujourd''hui à trois havanes, dont le Molino, nom de fabrique qui renvoie aux moulins du roman ; tout en tripe longue, medium.') WHERE `name` = 'Sancho Panza' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. No source consulted — neither Habanos nor the trade press — names its mother factory; the entry says so rather than choosing. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page confirms the first registration in 1848 and a range now reduced to three Havanas, including the Molino, a factory name that points to the novel''s windmills; all long filler, medium.') WHERE `name` = 'Sancho Panza' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Ninguna fuente consultada — ni Habanos, ni la prensa del oficio — nombra su fábrica madre; la ficha lo dice en vez de elegir. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial confirma el primer registro en 1848 y una gama reducida hoy a tres habanos, entre ellos el Molino, nombre de galera que remite a los molinos de la novela; toda con tripa larga, medium.') WHERE `name` = 'Sancho Panza' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Keine befragte Quelle — weder Habanos noch die Fachpresse — nennt ihre Mutterfabrik; der Eintrag sagt es, statt zu wählen. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite bestätigt die erste Eintragung 1848 und eine heute auf drei Havannas reduzierte Palette, darunter die Molino, ein Fabrikname, der auf die Windmühlen des Romans verweist; ganz Longfiller, medium.') WHERE `name` = 'Sancho Panza' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 查阅的来源——无论 Habanos 还是行业媒体——都没有点名它的母厂；词条如实说明，而不是自行挑选。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面确认1848年首次注册，系列如今缩减为三款哈瓦那雪茄，其中 Molino 这个厂内名称指向小说里的风车；全部长茄芯，中等浓度。') WHERE `name` = 'Sancho Panza' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. لا يسمّي أيّ مصدر راجعناه — لا Habanos ولا الصحافة المتخصّصة — مصنعها الأمّ؛ وتقول البطاقة ذلك بدل أن تختار. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تؤكّد الصفحة الرسمية التسجيل الأوّل سنة 1848 ومجموعة تقلّصت اليوم إلى ثلاثة سيجارات هافانية، منها Molino، اسم مصنع يحيل إلى طواحين الرواية؛ كلّها بحشوة طويلة، متوسّطة.') WHERE `name` = 'Sancho Panza' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Trinidad ──
UPDATE `brands` SET `factory` = 'Fabrique mère Francisco Donatien, Pinar del Río — faite aujourd''hui à Pinar del Río, dit la page officielle, après des années à El Laguito ; transfert au début des années 2000', `source` = 'habanos.com, page officielle Trinidad (lue le 14 septembre 2026 : marque de 1969, cadeaux diplomatiques ; vente publique en 1998 ; Fundadores seule vitole d''origine, Reyes, Coloniales et Robustos Extra en 2003, Robustos T en 2009, Esmeralda, Media Luna et Topes en 2019 ; faite plusieurs années à El Laguito, aujourd''hui à Pinar del Río) ; cubancigarwebsite.com « Tobacco and Cigar Production » (Francisco Donatien mère de Trinidad, transférée d''El Laguito au début des années 2000) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019 : haute valeur)' WHERE `name` = 'Trinidad';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Francisco Donatien, à Pinar del Río — un bâtiment de 1868, fabrique de cigares depuis 1961, relevée à la fin des années 1990. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, dans le groupe de quatre dit de haute valeur — Bolívar, Punch, Ramón Allones, Trinidad. La page officielle le dit : pendant plusieurs années Trinidad fut faite à El Laguito, la fabrique de Cohiba ; aujourd''hui elle est faite à Pinar del Río. La presse du métier date le transfert du début des années 2000 et nomme la fabrique, Francisco Donatien. L''atlas l''écrivait encore à El Laguito, et se corrige.') WHERE `name` = 'Trinidad' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Francisco Donatien, in Pinar del Río — an 1868 building, a cigar factory since 1961, upgraded in the late 1990s. Since 2019 Habanos has placed it among its twenty-one portfolio brands, in the group of four called high-value — Bolívar, Punch, Ramón Allones, Trinidad. The official page says it: for several years Trinidad was made at El Laguito, Cohiba''s factory; today it is made in Pinar del Río. The trade press dates the transfer to the early 2000s and names the factory, Francisco Donatien. This atlas still had it at El Laguito, and corrects itself.') WHERE `name` = 'Trinidad' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Francisco Donatien, en Pinar del Río — un edificio de 1868, fábrica de puros desde 1961, renovada a finales de los años noventa. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, en el grupo de cuatro llamado de alto valor — Bolívar, Punch, Ramón Allones, Trinidad. La página oficial lo dice: durante varios años Trinidad se hizo en El Laguito, la fábrica de Cohiba; hoy se hace en Pinar del Río. La prensa del oficio fecha el traslado a principios de los años 2000 y nombra la fábrica, Francisco Donatien. El atlas la ponía aún en El Laguito, y se corrige.') WHERE `name` = 'Trinidad' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Francisco Donatien in Pinar del Río — ein Gebäude von 1868, Zigarrenfabrik seit 1961, Ende der 1990er Jahre aufgewertet. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, in der Vierergruppe, die hochwertig genannt wird — Bolívar, Punch, Ramón Allones, Trinidad. Die offizielle Seite sagt es: Mehrere Jahre lang wurde Trinidad in El Laguito gemacht, der Fabrik von Cohiba; heute wird sie in Pinar del Río gemacht. Die Fachpresse datiert den Wechsel auf die frühen 2000er Jahre und nennt die Fabrik, Francisco Donatien. Dieser Atlas hatte sie noch in El Laguito und korrigiert sich.') WHERE `name` = 'Trinidad' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是比那尔德里奥的 Francisco Donatien 厂——1868年的建筑，1961年起做雪茄，1990年代末升级。 自2019年起，Habanos 把它列入二十一个组合品牌，属于所谓高价值的四个品牌一组——Bolívar、Punch、Ramón Allones、Trinidad。 官方页面写明：Trinidad 曾有几年在 Cohiba 的工厂 El Laguito 制作，如今在比那尔德里奥制作。行业媒体把转移定在2000年代初，并点出工厂名 Francisco Donatien。本图集原先仍写在 El Laguito，予以更正。') WHERE `name` = 'Trinidad' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Francisco Donatien في بينار ديل ريو — مبنى من 1868، مصنع سيجار منذ 1961، جُدّد في أواخر التسعينيات. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، في مجموعة الأربع المسمّاة عالية القيمة — Bolívar وPunch وRamón Allones وTrinidad. تقول الصفحة الرسمية ذلك: لسنوات عدّة صُنعت Trinidad في El Laguito، مصنع Cohiba؛ واليوم تُصنع في بينار ديل ريو. تؤرّخ الصحافة المتخصّصة النقل بمطلع الألفية وتسمّي المصنع، Francisco Donatien. وكان هذا الأطلس ما زال يضعها في El Laguito، ويصحّح نفسه.') WHERE `name` = 'Trinidad' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Vegas Robaina ──
UPDATE `brands` SET `factory` = 'Fabrique mère Francisco Donatien, Pinar del Río — selon la presse du métier ; la famille Robaina cultive à Cuchillas de Barbacoa (San Luis) depuis 1845', `source` = 'habanos.com, page officielle Vegas Robaina (lue le 14 septembre 2026 : la famille Robaina cultive à Cuchillas de Barbacoa, district de San Luis, depuis 1845 ; marque créée en 1997 en hommage à Alejandro Robaina et aux planteurs ; cinq vitoles, tripe longue, medium à full) ; cubancigarwebsite.com « Tobacco and Cigar Production » (Francisco Donatien mère de Vegas Robaina) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019)' WHERE `name` = 'Vegas Robaina';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Francisco Donatien, à Pinar del Río — un bâtiment de 1868, fabrique de cigares depuis 1961, relevée à la fin des années 1990. Depuis 2019, Habanos la range dans ses vingt et une marques de portefeuille, hors des six globales. La page officielle fait remonter la vega familiale de Cuchillas de Barbacoa, dans le district de San Luis, à 1845, et la marque à 1997, en hommage à Alejandro Robaina et, à travers lui, à tous les planteurs ; cinq vitoles en tripe longue. Sa fabrique mère est à Pinar del Río même ; l''atlas l''écrivait chez El Rey del Mundo, et se corrige.') WHERE `name` = 'Vegas Robaina' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Francisco Donatien, in Pinar del Río — an 1868 building, a cigar factory since 1961, upgraded in the late 1990s. Since 2019 Habanos has placed it among its twenty-one portfolio brands, outside the six global ones. The official page traces the family vega at Cuchillas de Barbacoa, in the San Luis district, to 1845, and the brand to 1997, in homage to Alejandro Robaina and, through him, to all growers; five sizes in long filler. Its mother factory is in Pinar del Río itself; this atlas had it at El Rey del Mundo, and corrects itself.') WHERE `name` = 'Vegas Robaina' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Francisco Donatien, en Pinar del Río — un edificio de 1868, fábrica de puros desde 1961, renovada a finales de los años noventa. Desde 2019 Habanos la clasifica entre sus veintiuna marcas de portafolio, fuera de las seis globales. La página oficial remonta la vega familiar de Cuchillas de Barbacoa, en el distrito de San Luis, a 1845, y la marca a 1997, en homenaje a Alejandro Robaina y, a través de él, a todos los vegueros; cinco vitolas con tripa larga. Su fábrica madre está en el propio Pinar del Río; el atlas la ponía en El Rey del Mundo, y se corrige.') WHERE `name` = 'Vegas Robaina' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Francisco Donatien in Pinar del Río — ein Gebäude von 1868, Zigarrenfabrik seit 1961, Ende der 1990er Jahre aufgewertet. Seit 2019 zählt Habanos sie zu seinen einundzwanzig Portfoliomarken, außerhalb der sechs globalen. Die offizielle Seite führt die Familien-Vega in Cuchillas de Barbacoa, im Distrikt San Luis, auf 1845 zurück und die Marke auf 1997, zu Ehren Alejandro Robainas und durch ihn aller Pflanzer; fünf Formate in Longfiller. Ihre Mutterfabrik liegt in Pinar del Río selbst; dieser Atlas hatte sie bei El Rey del Mundo und korrigiert sich.') WHERE `name` = 'Vegas Robaina' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是比那尔德里奥的 Francisco Donatien 厂——1868年的建筑，1961年起做雪茄，1990年代末升级。 自2019年起，Habanos 把它列入六个全球品牌之外的二十一个组合品牌。 官方页面把家族在圣路易斯区库奇亚斯-德巴尔瓦科亚的烟田追溯到1845年，把品牌定在1997年，以纪念亚历杭德罗·罗瓦伊纳并借他致敬所有种植者；五款规格皆为长茄芯。它的母厂就在比那尔德里奥；本图集原先写在 El Rey del Mundo，予以更正。') WHERE `name` = 'Vegas Robaina' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Francisco Donatien في بينار ديل ريو — مبنى من 1868، مصنع سيجار منذ 1961، جُدّد في أواخر التسعينيات. منذ 2019 تصنّفها Habanos ضمن علامات المحفظة الإحدى والعشرين، خارج العلامات العالمية الستّ. تعيد الصفحة الرسمية مزرعة العائلة في كوتشيّاس دي بارباكوا، بمقاطعة سان لويس، إلى 1845، والعلامة إلى 1997 تكريمًا لأليخاندرو روباينا ومن خلاله لكلّ المزارعين؛ خمسة قياسات بحشوة طويلة. ومصنعها الأمّ في بينار ديل ريو نفسها؛ وكان هذا الأطلس يضعها عند El Rey del Mundo، ويصحّح نفسه.') WHERE `name` = 'Vegas Robaina' AND `history_ar` NOT LIKE '%مصنع أمّ%';

-- ── Vegueros ──
UPDATE `brands` SET `factory` = 'Fabrique Francisco Donatien, Pinar del Río — bâtiment de 1868, fabrique de cigares depuis 1961, nommée par la page officielle', `source` = 'habanos.com, page officielle Vegueros (lue le 14 septembre 2026 : introduite en 1996 ; hommage aux planteurs de Pinar del Río ; fabrique Francisco Donatien, bâtiment de 1868 converti en 1961 ; Tapados, Entretiempos, Mañanitas, Centrofinos, boîtes métalliques de seize ; tripe longue, medium à full) — l''ancienne lecture donnait une relance en 1997 ; cubancigarwebsite.com « Tobacco and Cigar Production » (Francisco Donatien relevée à la fin des années 1990 pour Vegueros) ; cigaraficionado.com « Cuba Changes Classification of Cigar Brands » (1er août 2019 : marque de volume)', `founded` = '1996 (Habanos) ou 1997 — Pinar del Río, Cuba' WHERE `name` = 'Vegueros';
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa fabrique mère est Francisco Donatien, à Pinar del Río — un bâtiment de 1868, fabrique de cigares depuis 1961, relevée à la fin des années 1990. Depuis 2019, Habanos la range dans ses trois marques de volume — José L. Piedra, Quintero, Vegueros —, les moins chères du portefeuille. La page officielle la date de 1996 — l''atlas écrivait 1997, l''année de la relance selon d''autres lectures, et garde les deux — et nomme sa fabrique, Francisco Donatien, un bâtiment de 1868 converti en 1961 ; la gamme a été refaite au bout de quinze ans avec les Tapados, Entretiempos, Mañanitas et Centrofinos, en boîtes métalliques de seize.') WHERE `name` = 'Vegueros' AND `history` NOT LIKE '%fabrique mère%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its mother factory is Francisco Donatien, in Pinar del Río — an 1868 building, a cigar factory since 1961, upgraded in the late 1990s. Since 2019 Habanos has placed it among its three volume brands — José L. Piedra, Quintero, Vegueros —, the cheapest in the portfolio. The official page dates it to 1996 — this atlas had 1997, the year of the relaunch by other readings, and keeps both — and names its factory, Francisco Donatien, an 1868 building converted in 1961; the range was remade after fifteen years with Tapados, Entretiempos, Mañanitas and Centrofinos, in tins of sixteen.') WHERE `name` = 'Vegueros' AND `history_en` NOT LIKE '%mother factory%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su fábrica madre es Francisco Donatien, en Pinar del Río — un edificio de 1868, fábrica de puros desde 1961, renovada a finales de los años noventa. Desde 2019 Habanos la clasifica entre sus tres marcas de volumen — José L. Piedra, Quintero, Vegueros —, las más baratas del portafolio. La página oficial la fecha en 1996 — el atlas escribía 1997, el año del relanzamiento según otras lecturas, y conserva las dos — y nombra su fábrica, Francisco Donatien, un edificio de 1868 convertido en 1961; la gama se rehízo al cabo de quince años con los Tapados, Entretiempos, Mañanitas y Centrofinos, en latas de dieciséis.') WHERE `name` = 'Vegueros' AND `history_es` NOT LIKE '%fábrica madre%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Mutterfabrik ist Francisco Donatien in Pinar del Río — ein Gebäude von 1868, Zigarrenfabrik seit 1961, Ende der 1990er Jahre aufgewertet. Seit 2019 zählt Habanos sie zu seinen drei Volumenmarken — José L. Piedra, Quintero, Vegueros —, den günstigsten des Portfolios. Die offizielle Seite datiert sie auf 1996 — dieser Atlas hatte 1997, das Jahr des Neustarts nach anderen Lesungen, und behält beide — und nennt ihre Fabrik, Francisco Donatien, ein Gebäude von 1868, 1961 umgewandelt; die Palette wurde nach fünfzehn Jahren mit Tapados, Entretiempos, Mañanitas und Centrofinos neu gemacht, in Dosen zu sechzehn.') WHERE `name` = 'Vegueros' AND `history_de` NOT LIKE '%Mutterfabrik%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。 它的母厂是比那尔德里奥的 Francisco Donatien 厂——1868年的建筑，1961年起做雪茄，1990年代末升级。 自2019年起，Habanos 把它列为三个量产品牌之一——José L. Piedra、Quintero、Vegueros——组合里价格低的一档。 官方页面把它定在1996年——本图集原写1997年，那是其他读法里重新推出的年份，两者都保留——并点出它的工厂 Francisco Donatien，一座1868年的建筑，1961年改造；十五年后系列重做，推出 Tapados、Entretiempos、Mañanitas 和 Centrofinos，十六支金属盒装。') WHERE `name` = 'Vegueros' AND `history_zh` NOT LIKE '%母厂%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. مصنعها الأمّ هو Francisco Donatien في بينار ديل ريو — مبنى من 1868، مصنع سيجار منذ 1961، جُدّد في أواخر التسعينيات. منذ 2019 تصنّفها Habanos ضمن علامات الحجم الثلاث — José L. Piedra وQuintero وVegueros — وهي الأرخص في المحفظة. تؤرّخها الصفحة الرسمية بسنة 1996 — كان الأطلس يكتب 1997، سنة إعادة الإطلاق بحسب قراءات أخرى، ويحتفظ بالاثنتين — وتسمّي مصنعها، Francisco Donatien، مبنى من 1868 حُوّل سنة 1961؛ وأُعيدت المجموعة بعد خمسة عشر عامًا بـTapados وEntretiempos وMañanitas وCentrofinos، في علب معدنية من ستّ عشرة.') WHERE `name` = 'Vegueros' AND `history_ar` NOT LIKE '%مصنع أمّ%';


INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, 'history', l.lang, SHA1(b.`history`), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Bolivar','Cohiba','Cuaba','Diplomáticos','El Rey del Mundo','Fonseca','H. Upmann','Hoyo de Monterrey','José L. Piedra','Juan López','La Flor de Cano','La Gloria Cubana','Montecristo','Partagás','Por Larrañaga','Punch','Quai d''Orsay','Quintero','Rafael González','Ramón Allones','Romeo y Julieta','Saint Luis Rey','San Cristóbal de La Habana','Sancho Panza','Trinidad','Vegas Robaina','Vegueros')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

