  (NULL,'migration 226','systeme','vingt_sept_fiches_cubaines_relues','marque',0,
   'Les 27 fiches cubaines relues contre les pages officielles de habanos.com, cubancigarwebsite.com et la presse du metier. Un paragraphe ajoute a chaque histoire, six langues : politique des fabriques meres (2002), fabrique mere, classement de 2019, tripe courte, dates divergentes'),
  (NULL,'migration 226','systeme','sept_fabriques_corrigees','marque',0,
   'Bolivar est a Partagas et non chez Romeo y Julieta ; Trinidad a Pinar del Rio et non a El Laguito ; Punch et Hoyo a La Corona ; Quintero a Cienfuegos et Vegas Robaina a Francisco Donatien, et non chez El Rey del Mundo, fabrique qui n existe plus sous ce nom ; Partagas a San Carlos 806'),
  (NULL,'migration 226','systeme','quatre_meres_non_nommees','marque',0,
   'Fonseca, Juan Lopez, Rafael Gonzalez, Sancho Panza : aucune source consultee ne nomme leur fabrique mere. La fiche le dit (regle 220). Six dates divergentes ecrites : El Rey del Mundo 1848/1882, Rafael Gonzalez 1928/annees 1930, Saint Luis Rey, Vegueros 1996/1997, Jose L. Piedra, La Flor de Cano');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `country_id` = 'cuba') = 27 AS vingt_sept,
  (SELECT SUM(`history` LIKE '%fabrique mère%' AND `history_en` LIKE '%mother factory%' AND `history_es` LIKE '%fábrica madre%' AND `history_de` LIKE '%Mutterfabrik%' AND `history_zh` LIKE '%母厂%' AND `history_ar` LIKE '%مصنع أمّ%') FROM `brands` WHERE `country_id` = 'cuba') = 27 AS six_langues_marquees,
  (SELECT SUM(`factory` IN ('La Havane, Cuba', 'Cuba', 'Pinar del Río, Cuba') OR `factory` LIKE '%El Rey del Mundo, La Havane%') FROM `brands` WHERE `country_id` = 'cuba') = 0 AS plus_de_fabrique_muette,
  (SELECT SUM(CHAR_LENGTH(`source`) < 300) FROM `brands` WHERE `country_id` = 'cuba') = 0 AS sources_entieres,
  -- Plus de controle a 255 sur le journal : `detail` est un TEXT depuis la 225.
  (SELECT SUM(CHAR_LENGTH(`founded`) >= 50) FROM `brands` WHERE `country_id` = 'cuba') = 0 AS founded_sous_50;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
